/* ---- js/fx/particles.js ---- */
/* War Train — particle VFX: smoke, steam, sparks, embers, tracers, muzzle flashes, energy blasts,
   shockwaves and celebration bursts. Everything is drawn with alpha on a transparent canvas. */
window.WT = window.WT || {};
(function (WT) {
  'use strict';
  const U = WT.U;

  function radialSprite(r, g, b, soft) {
    const s = 128, c = U.canvas(s, s), x = c.getContext('2d');
    const grd = x.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
    grd.addColorStop(0, `rgba(${r},${g},${b},1)`);
    grd.addColorStop(soft, `rgba(${r},${g},${b},0.45)`);
    grd.addColorStop(1, `rgba(${r},${g},${b},0)`);
    x.fillStyle = grd;
    x.fillRect(0, 0, s, s);
    return c;
  }

  // Lumpy smoke puff so clouds don't look like perfect circles.
  function smokeSprite(r, g, b, seed) {
    const s = 128, c = U.canvas(s, s), x = c.getContext('2d'), rnd = U.rng(seed);
    for (let i = 0; i < 9; i++) {
      const px = s / 2 + (rnd() - 0.5) * 40, py = s / 2 + (rnd() - 0.5) * 40, pr = 22 + rnd() * 22;
      const grd = x.createRadialGradient(px, py, 0, px, py, pr);
      grd.addColorStop(0, `rgba(${r},${g},${b},0.35)`);
      grd.addColorStop(1, `rgba(${r},${g},${b},0)`);
      x.fillStyle = grd;
      x.fillRect(0, 0, s, s);
    }
    return c;
  }

  class FX {
    constructor(quality) {
      this.mult = quality === 'low' ? 0.45 : 1;
      this.max = quality === 'low' ? 900 : 2600;
      this.p = [];
      this.rnd = U.rng(1337);
      this.shakeAmt = 0;
      this.shakeT = 0;
      this.sprites = {
        smoke: [smokeSprite(26, 26, 30, 1), smokeSprite(34, 30, 30, 2), smokeSprite(22, 22, 26, 3)],
        warm: [smokeSprite(70, 44, 30, 4), smokeSprite(60, 36, 28, 5)],
        steam: [smokeSprite(205, 205, 212, 6), smokeSprite(190, 192, 200, 7)],
        orange: radialSprite(255, 130, 30, 0.25),
        red: radialSprite(255, 50, 30, 0.25),
        white: radialSprite(255, 240, 210, 0.2),
        gold: radialSprite(255, 200, 70, 0.25),
        hot: radialSprite(255, 236, 170, 0.35),
        soot: [smokeSprite(12, 11, 12, 8), smokeSprite(18, 15, 14, 9)],
      };
    }

    reset(seed) {
      this.p.length = 0;
      this.rnd = U.rng(seed || 1337);
      this.shakeAmt = 0;
    }

    r(a, b) { return a + (b - a) * this.rnd(); }
    n(count) { return Math.max(1, Math.round(count * this.mult)); }

    add(o) {
      if (this.p.length >= this.max) this.p.shift();
      o.age = 0;
      o.layer = o.layer || 'front';
      this.p.push(o);
      return o;
    }

    shake(amount, dur) {
      this.shakeAmt = Math.max(this.shakeAmt, amount);
      this.shakeT = Math.max(this.shakeT, dur || 0.4);
    }
    shakeOffset(t) {
      if (this.shakeAmt < 0.05) return [0, 0];
      return [Math.sin(t * 91) * this.shakeAmt + Math.sin(t * 37) * this.shakeAmt * 0.5, Math.cos(t * 83) * this.shakeAmt * 0.7];
    }

    // ---- emitters -------------------------------------------------------
    smoke(x, y, o) {
      o = o || {};
      const cnt = this.n(o.n || 4);
      for (let i = 0; i < cnt; i++) {
        const set = o.kind === 'steam' ? this.sprites.steam : o.kind === 'warm' ? this.sprites.warm : o.kind === 'soot' ? this.sprites.soot : this.sprites.smoke;
        this.add({
          t: 'smoke', spr: set[(this.rnd() * set.length) | 0], layer: o.layer || 'back',
          x: x + this.r(-1, 1) * (o.spread || 10), y: y + this.r(-1, 1) * (o.spread || 10),
          vx: (o.vx || 0) + this.r(-1, 1) * (o.jitter || 20), vy: (o.vy || -40) + this.r(-1, 1) * (o.jitter || 20),
          size: (o.size || 70) * this.r(0.7, 1.3), grow: o.grow || 1.8, life: (o.life || 2.2) * this.r(0.7, 1.2),
          alpha: o.alpha || 0.8, drag: o.drag || 0.6, rot: this.r(0, 6.28), vr: this.r(-0.4, 0.4),
        });
      }
    }
    steam(x, y, o) { this.smoke(x, y, Object.assign({ kind: 'steam', alpha: 0.55, size: 50, life: 1.3, vy: -120, jitter: 40, layer: 'front' }, o)); }

    sparks(x, y, o) {
      o = o || {};
      const cnt = this.n(o.n || 20);
      for (let i = 0; i < cnt; i++) {
        const a = (o.angle || -Math.PI / 2) + this.r(-1, 1) * (o.spread || Math.PI), sp = (o.speed || 500) * this.r(0.3, 1.1);
        this.add({
          t: 'spark', layer: o.layer || 'front', x, y, vx: Math.cos(a) * sp + (o.vx || 0), vy: Math.sin(a) * sp, life: this.r(0.25, 0.8) * (o.life || 1),
          g: o.gravity == null ? 900 : o.gravity, drag: 1.5, w: this.r(1.2, 2.6), color: o.color || (this.rnd() < 0.7 ? '255,170,60' : '255,240,200'),
        });
      }
    }

    embers(x, y, o) {
      o = o || {};
      const cnt = this.n(o.n || 6);
      for (let i = 0; i < cnt; i++) {
        this.add({
          t: 'ember', layer: o.layer || 'front', x: x + this.r(-1, 1) * (o.spread || 30), y: y + this.r(-1, 1) * (o.spread || 30),
          vx: (o.vx || 0) + this.r(-30, 30), vy: this.r(-90, -20) * (o.lift || 1), life: this.r(1.2, 3.2) * (o.life || 1),
          g: -10, drag: 0.4, size: this.r(1.5, 4), ph: this.r(0, 6.28),
        });
      }
    }

    flash(x, y, size, angle, o) {
      o = o || {};
      this.add({ t: 'flash', x, y, size, angle: angle || 0, life: o.life || 0.12, layer: o.layer || 'front', spr: o.color === 'white' ? this.sprites.white : this.sprites.orange, alpha: o.alpha || 1 });
    }

    glow(x, y, size, o) {
      o = o || {};
      this.add({ t: 'glow', x, y, vx: o.vx || 0, vy: o.vy || 0, size, life: o.life || 0.5, layer: o.layer || 'front', spr: this.sprites[o.color || 'orange'], alpha: o.alpha == null ? 1 : o.alpha, drag: 0 });
    }

    tracer(x, y, angle, o) {
      o = o || {};
      const sp = o.speed || 2600;
      this.add({ t: 'tracer', x, y, vx: Math.cos(angle) * sp, vy: Math.sin(angle) * sp, life: o.life || 0.6, len: o.len || 90, layer: o.layer || 'front', color: o.color || '255,190,90', drag: 0 });
    }

    ring(x, y, maxR, o) {
      o = o || {};
      this.add({ t: 'ring', x, y, maxR, life: o.life || 0.5, color: o.color || '255,150,60', w: o.w || 6, layer: 'front' });
    }

    // Harmless cinematic energy projectile; bursts into a celebration flare at the end of its life.
    blast(x, y, angle, o) {
      o = o || {};
      const life = o.life || 0.7, sp = o.speed || 1500;
      let vx = Math.cos(angle) * sp, vy = Math.sin(angle) * sp, g = 380, drag = 0.25;
      if (o.target) { vx = (o.target[0] - x) / life; vy = (o.target[1] - y) / life; g = 0; drag = 0; }
      this.add({ t: 'blast', x, y, vx, vy, life, size: o.size || 26, g, drag, burst: o.burst !== false, scale: o.scale || 1, gold: !!o.gold, layer: 'front' });
    }

    burst(x, y, scale, gold) {
      scale = scale || 1;
      this.flash(x, y, 260 * scale, 0, { life: 0.25, color: 'white' });
      this.glow(x, y, 380 * scale, { life: 0.6, color: gold ? 'gold' : 'orange', alpha: 0.8 });
      this.ring(x, y, 120 * scale, { life: 0.45, w: 4, color: gold ? '255,190,80' : '255,140,50' });
      this.sparks(x, y, { n: 46 * scale, speed: 720 * scale, spread: Math.PI, gravity: 260, life: 1.6, color: gold ? '255,215,110' : undefined });
      this.embers(x, y, { n: 14 * scale, spread: 40 * scale });
      this.smoke(x, y, { n: 3, kind: 'warm', size: 90 * scale, alpha: 0.35, layer: 'front', vy: -10 });
    }

    // Big muzzle event used by every cannon.
    muzzle(x, y, angle, scale) {
      scale = scale || 1;
      this.flash(x, y, 200 * scale, angle, { life: 0.1, color: 'white' });
      this.flash(x + Math.cos(angle) * 40 * scale, y + Math.sin(angle) * 40 * scale, 260 * scale, angle, { life: 0.16 });
      this.glow(x, y, 300 * scale, { life: 0.35, alpha: 0.7 });
      this.sparks(x, y, { n: 26 * scale, angle, spread: 0.6, speed: 900 * scale, gravity: 500 });
      this.smoke(x, y, { n: 6 * scale, angle, vx: Math.cos(angle) * 160, vy: Math.sin(angle) * 160 - 30, size: 70 * scale, alpha: 0.75, layer: 'front', life: 2 });
      this.smoke(x, y, { n: 3, kind: 'warm', vx: Math.cos(angle) * 90, vy: -40, size: 60 * scale, alpha: 0.5, layer: 'front' });
      this.ring(x, y, 70 * scale, { life: 0.22, w: 2, color: '255,170,90' });
    }

    // ---- war effects ----------------------------------------------------
    // Rising flames: white-hot core → orange → red, fading into soot.
    fire(x, y, o) {
      o = o || {};
      const cnt = this.n(o.n || 3);
      for (let i = 0; i < cnt; i++) {
        this.add({
          t: 'fire', layer: o.layer || 'front', x: x + this.r(-1, 1) * (o.spread || 8), y: y + this.r(-1, 1) * (o.spread || 8) * 0.5,
          vx: (o.vx || 0) + this.r(-1, 1) * (o.jitter || 25), vy: (o.vy || -90) + this.r(-1, 1) * (o.jitter || 25),
          size: (o.size || 26) * this.r(0.7, 1.3), life: (o.life || 0.8) * this.r(0.7, 1.2), g: o.g == null ? -120 : o.g, drag: o.drag || 1.2,
          rot: this.r(0, 6.28),
        });
      }
    }

    debris(x, y, o) {
      o = o || {};
      const cnt = this.n(o.n || 8);
      for (let i = 0; i < cnt; i++) {
        const a = (o.angle == null ? -Math.PI / 2 : o.angle) + this.r(-1, 1) * (o.spread || 1.2), sp = (o.speed || 700) * this.r(0.35, 1);
        this.add({
          t: 'debris', layer: o.layer || 'front', x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, g: 1300, drag: 0.3,
          life: this.r(0.9, 1.8), w: this.r(4, 12) * (o.scale || 1), h: this.r(3, 7) * (o.scale || 1), rot: this.r(0, 6.28), vr: this.r(-14, 14),
          burning: this.rnd() < (o.burning == null ? 0.5 : o.burning),
        });
      }
    }

    // Missile with a smoke trail; explodes on arrival.
    missile(x, y, tx, ty, o) {
      o = o || {};
      const life = o.life || 0.7;
      this.add({ t: 'missile', layer: o.layer || 'front', x, y, vx: (tx - x) / life, vy: (ty - y) / life, life, drag: 0, end: o.end || 'explode', scale: o.scale || 1, endLayer: o.endLayer || 'back' });
    }

    // Airborne fireball.
    explosion(x, y, s, o) {
      o = o || {};
      s = s || 1;
      const layer = o.layer || 'front';
      this.flash(x, y, 420 * s, 0, { life: 0.12, color: 'white', layer });
      this.glow(x, y, 700 * s, { life: 0.5, alpha: 0.9, layer });
      this.ring(x, y, 220 * s, { life: 0.4, w: 5 });
      for (let i = 0; i < this.n(26 * s); i++) {
        const a = this.r(0, 6.283), sp = this.r(60, 340) * s;
        this.add({ t: 'fire', layer, x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 60, size: this.r(30, 60) * s, life: this.r(0.5, 1.1), g: -160, drag: 2.6, rot: this.r(0, 6.28) });
      }
      this.smoke(x, y, { n: 10 * s, size: 90 * s, spread: 50 * s, jitter: 90 * s, vy: -50, life: 3, alpha: 0.85, layer, grow: 2.2 });
      this.debris(x, y, { n: 10 * s, speed: 800 * s, spread: Math.PI, layer: 'front', scale: Math.min(2, s) });
      this.sparks(x, y, { n: 30 * s, speed: 900 * s, gravity: 700, life: 1.2 });
      if (o.shake !== false) this.shake(8 * s, 0.3);
    }

    // Ground impact: fire column + dust skirt + debris arcs.
    groundBlast(x, y, s, o) {
      o = o || {};
      s = s || 1;
      const layer = o.layer || 'back';
      this.flash(x, y - 40 * s, 460 * s, 0, { life: 0.12, color: 'white', layer });
      this.glow(x, y - 60 * s, 800 * s, { life: 0.6, alpha: 0.85, layer });
      for (let i = 0; i < this.n(30 * s); i++) {
        const a = -Math.PI / 2 + this.r(-0.55, 0.55), sp = this.r(150, 620) * s;
        this.add({ t: 'fire', layer, x: x + this.r(-20, 20) * s, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, size: this.r(34, 70) * s, life: this.r(0.6, 1.2), g: 80, drag: 1.8, rot: this.r(0, 6.28) });
      }
      // dust skirt rolling sideways along the ground
      for (const dir of [-1, 1]) this.smoke(x, y - 10, { n: 5 * s, kind: 'warm', vx: dir * 260 * s, vy: -25, jitter: 40, size: 70 * s, life: 1.8, alpha: 0.6, layer, grow: 2 });
      this.smoke(x, y - 120 * s, { n: 9 * s, kind: 'soot', size: 110 * s, spread: 60 * s, vy: -90, jitter: 50, life: 3.4, alpha: 0.9, layer, grow: 2.4 });
      const near = o.near ? 'front' : layer; // impacts behind the train keep their debris behind it
      this.debris(x, y - 10, { n: 12 * s, speed: 900 * s, spread: 0.9, layer: near, scale: Math.min(2, s) });
      this.sparks(x, y - 20, { n: 24 * s, speed: 800 * s, spread: 0.9, gravity: 900, life: 1.3, layer: near });
      this.embers(x, y - 80 * s, { n: 14 * s, spread: 60 * s, lift: 1.5, layer });
      if (o.shake !== false) this.shake(9 * s, 0.35);
    }

    // ---- simulation -----------------------------------------------------
    update(dt) {
      const cur = this.p, keep = [], bursts = [];
      this.p = []; // particles spawned during this step land here
      for (let i = 0; i < cur.length; i++) {
        const q = cur[i];
        q.age += dt;
        if (q.age >= q.life) {
          if ((q.t === 'blast' && q.burst) || q.end) bursts.push(q);
          continue;
        }
        if (q.vx !== undefined) {
          const dr = Math.exp(-(q.drag || 0) * dt);
          q.vx *= dr; q.vy *= dr;
          q.vy += (q.g || 0) * dt;
          q.x += q.vx * dt; q.y += q.vy * dt;
        }
        if (q.t === 'missile') {
          // several puffs per frame along the path so the trail reads as one continuous plume
          for (let k = 0; k < 4; k++) {
            const f = k / 4;
            this.add({ t: 'smoke', spr: this.sprites.steam[(this.rnd() * 2) | 0], layer: q.layer, x: q.x - q.vx * dt * f, y: q.y - q.vy * dt * f, vx: this.r(-8, 8), vy: this.r(-8, 3), size: 6 * q.scale, grow: 3, life: 1.0, alpha: 0.22, drag: 1, rot: this.r(0, 6), vr: 0 });
          }
        } else if (q.t === 'debris' && q.burning && this.rnd() < 0.6) {
          this.add({ t: 'ember', x: q.x, y: q.y, vx: 0, vy: 0, life: 0.4, g: -20, drag: 1, size: 3, ph: 0, layer: q.layer });
        }
        if (q.t === 'blast' && this.rnd() < 0.8) {
          this.add({ t: 'ember', x: q.x, y: q.y, vx: this.r(-40, 40), vy: this.r(-40, 40), life: this.r(0.3, 0.7), g: 0, drag: 1, size: this.r(2, 4), ph: 0, layer: 'front' });
        }
        if (q.vr) q.rot += q.vr * dt;
        keep.push(q);
      }
      this.p = keep.concat(this.p);
      for (const q of bursts) {
        if (q.end === 'explode') this.explosion(q.x, q.y, q.scale, { layer: q.endLayer });
        else if (q.end === 'ground') this.groundBlast(q.x, q.y, q.scale, { layer: q.endLayer });
        else this.burst(q.x, q.y, q.scale, q.gold);
      }
      if (this.p.length > this.max) this.p.splice(0, this.p.length - this.max);
      if (this.shakeT > 0) this.shakeT -= dt;
      else this.shakeAmt *= Math.exp(-10 * dt);
    }

    draw(ctx, layer) {
      for (let i = 0; i < this.p.length; i++) {
        const q = this.p[i];
        if (q.layer !== layer) continue;
        const k = q.age / q.life;
        switch (q.t) {
          case 'smoke': {
            const s = q.size * (1 + (q.grow - 1) * U.easeOutCubic(k));
            ctx.globalAlpha = q.alpha * Math.min(1, k * 6) * (1 - k);
            ctx.save();
            ctx.translate(q.x, q.y);
            ctx.rotate(q.rot);
            ctx.drawImage(q.spr, -s, -s, s * 2, s * 2);
            ctx.restore();
            break;
          }
          case 'spark': {
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 1 - k;
            ctx.strokeStyle = `rgb(${q.color})`;
            ctx.lineWidth = q.w;
            ctx.beginPath();
            ctx.moveTo(q.x, q.y);
            ctx.lineTo(q.x - q.vx * 0.03, q.y - q.vy * 0.03);
            ctx.stroke();
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
          case 'ember': {
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = (1 - k) * (0.6 + 0.4 * Math.sin(q.age * 14 + q.ph));
            const s = q.size * 4;
            ctx.drawImage(this.sprites.orange, q.x - s, q.y - s, s * 2, s * 2);
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
          case 'flash': {
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = q.alpha * (1 - k);
            ctx.save();
            ctx.translate(q.x, q.y);
            ctx.rotate(q.angle);
            const s = q.size * (0.7 + 0.5 * k);
            ctx.drawImage(q.spr, -s * 0.6, -s * 0.35, s * 1.6, s * 0.7);
            ctx.drawImage(q.spr, -s * 0.35, -s * 0.35, s * 0.7, s * 0.7);
            ctx.restore();
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
          case 'glow': {
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = q.alpha * (1 - k);
            const s = q.size / 2;
            ctx.drawImage(q.spr, q.x - s, q.y - s, s * 2, s * 2);
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
          case 'tracer': {
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 1 - k * 0.5;
            const sp = Math.hypot(q.vx, q.vy), ux = q.vx / sp, uy = q.vy / sp;
            const grd = ctx.createLinearGradient(q.x, q.y, q.x - ux * q.len, q.y - uy * q.len);
            grd.addColorStop(0, `rgba(255,250,230,1)`);
            grd.addColorStop(0.2, `rgba(${q.color},0.9)`);
            grd.addColorStop(1, `rgba(${q.color},0)`);
            ctx.strokeStyle = grd;
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(q.x, q.y);
            ctx.lineTo(q.x - ux * q.len, q.y - uy * q.len);
            ctx.stroke();
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
          case 'ring': {
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 1 - k;
            ctx.strokeStyle = `rgb(${q.color})`;
            ctx.lineWidth = q.w * (1 - k) + 1;
            ctx.beginPath();
            ctx.arc(q.x, q.y, q.maxR * U.easeOutCubic(k), 0, Math.PI * 2);
            ctx.stroke();
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
          case 'fire': {
            ctx.globalCompositeOperation = 'lighter';
            const s = q.size * (0.6 + 0.9 * k);
            const spr = k < 0.18 ? this.sprites.hot : k < 0.55 ? this.sprites.orange : this.sprites.red;
            ctx.globalAlpha = (k < 0.1 ? k / 0.1 : 1 - (k - 0.1) / 0.9) * 0.9;
            ctx.drawImage(spr, q.x - s, q.y - s * 1.2, s * 2, s * 2.4);
            ctx.globalCompositeOperation = 'source-over';
            if (k > 0.55) { // charred tip turning into soot
              ctx.globalAlpha = (k - 0.55) * 0.9;
              ctx.drawImage(this.sprites.soot[0], q.x - s, q.y - s, s * 2, s * 2);
            }
            break;
          }
          case 'debris': {
            ctx.globalAlpha = 1 - Math.max(0, k - 0.7) / 0.3;
            ctx.save();
            ctx.translate(q.x, q.y);
            ctx.rotate(q.rot);
            ctx.fillStyle = q.burning ? '#2a1a10' : '#15171a';
            ctx.fillRect(-q.w / 2, -q.h / 2, q.w, q.h);
            if (q.burning) { ctx.fillStyle = 'rgba(255,120,30,0.9)'; ctx.fillRect(-q.w / 2, -q.h / 2, q.w * 0.4, q.h); }
            ctx.restore();
            break;
          }
          case 'missile': {
            const sp = Math.hypot(q.vx, q.vy) || 1, ux = q.vx / sp, uy = q.vy / sp, L = 26 * q.scale;
            ctx.globalAlpha = 1;
            ctx.strokeStyle = '#2b2f34'; ctx.lineWidth = 5 * q.scale; ctx.lineCap = 'round';
            ctx.beginPath(); ctx.moveTo(q.x, q.y); ctx.lineTo(q.x - ux * L, q.y - uy * L); ctx.stroke();
            ctx.lineCap = 'butt';
            ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(this.sprites.hot, q.x - ux * L - 14 * q.scale, q.y - uy * L - 14 * q.scale, 28 * q.scale, 28 * q.scale);
            ctx.drawImage(this.sprites.orange, q.x - ux * L - 40 * q.scale, q.y - uy * L - 40 * q.scale, 80 * q.scale, 80 * q.scale);
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
          case 'bomb': {
            ctx.globalAlpha = 1;
            ctx.save();
            ctx.translate(q.x, q.y);
            ctx.rotate(Math.atan2(q.vy, q.vx));
            ctx.fillStyle = '#1d2024';
            U.roundRect(ctx, -14, -5, 26, 10, 5); ctx.fill();
            ctx.fillStyle = '#3a3f45'; ctx.fillRect(-18, -6, 5, 12);
            ctx.fillStyle = '#c0261a'; ctx.fillRect(4, -5, 2, 10);
            ctx.restore();
            break;
          }
          case 'blast': {
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 1;
            const s = q.size * (1 + 0.15 * Math.sin(q.age * 60));
            const spr = q.gold ? this.sprites.gold : this.sprites.orange;
            ctx.drawImage(spr, q.x - s * 2.5, q.y - s * 2.5, s * 5, s * 5);
            ctx.drawImage(this.sprites.white, q.x - s, q.y - s, s * 2, s * 2);
            // streak
            const sp = Math.hypot(q.vx, q.vy) || 1;
            ctx.strokeStyle = 'rgba(255,170,70,0.6)';
            ctx.lineWidth = s * 0.6;
            ctx.beginPath();
            ctx.moveTo(q.x, q.y);
            ctx.lineTo(q.x - (q.vx / sp) * 110, q.y - (q.vy / sp) * 110);
            ctx.stroke();
            ctx.globalCompositeOperation = 'source-over';
            break;
          }
        }
      }
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
    }
  }

  WT.FX = FX;
})(window.WT);

/* ---- js/train/parts.js ---- */
/* War Train — procedural drawing kit: armor plates, rivets, hazard stripes, wheels, bogies,
   cannons, skull insignia, crowns, flags, chains and crates. All coordinates are design pixels. */
window.WT = window.WT || {};
(function (WT) {
  'use strict';
  const U = WT.U;
  const P = {};

  P.FONT_STENCIL = '"Black Ops One", Impact, "Arial Black", sans-serif';
  P.FONT_UI = 'Oswald, "Arial Narrow", "Roboto Condensed", Arial, sans-serif';
  P.WHEEL_Y = 918;
  P.WHEEL_R = 30;

  const TONES = [
    ['#5a6169', '#33393f', '#1a1d21'], // gunmetal
    ['#3d4146', '#22262a', '#101214'], // dark steel
    ['#2a2c2f', '#17181a', '#0a0a0b'], // matte black
    ['#55503f', '#36332a', '#1c1b16'], // olive drab
  ];

  P.metal = (ctx, y0, y1, tone) => {
    const t = TONES[tone || 0], g = ctx.createLinearGradient(0, y0, 0, y1);
    g.addColorStop(0, t[0]);
    g.addColorStop(0.18, t[1]);
    g.addColorStop(1, t[2]);
    return g;
  };

  P.rivets = (ctx, x, y, w, spacing, r) => {
    r = r || 2.2;
    for (let px = x; px <= x + w + 0.1; px += spacing) {
      ctx.fillStyle = '#0c0d0f';
      ctx.beginPath(); ctx.arc(px, y + 0.8, r, 0, 6.283); ctx.fill();
      ctx.fillStyle = '#8a9099';
      ctx.beginPath(); ctx.arc(px - 0.6, y - 0.4, r * 0.55, 0, 6.283); ctx.fill();
    }
  };

  P.plate = (ctx, x, y, w, h, o) => {
    o = o || {};
    U.chamfer(ctx, x, y, w, h, o.c == null ? 8 : o.c);
    ctx.fillStyle = P.metal(ctx, y, y + h, o.tone);
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = 'rgba(0,0,0,0.85)';
    ctx.stroke();
    // bevel highlight on the top edge
    ctx.strokeStyle = 'rgba(255,255,255,0.13)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(x + (o.c || 8) + 2, y + 2);
    ctx.lineTo(x + w - (o.c || 8) - 2, y + 2);
    ctx.stroke();
    // grime toward the bottom
    const g = ctx.createLinearGradient(0, y + h * 0.55, 0, y + h);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(1, 'rgba(10,6,4,0.45)');
    U.chamfer(ctx, x, y, w, h, o.c == null ? 8 : o.c);
    ctx.fillStyle = g;
    ctx.fill();
    if (o.rivets !== false) {
      const sp = o.spacing || 22;
      P.rivets(ctx, x + 10, y + 7, w - 20, sp);
      P.rivets(ctx, x + 10, y + h - 7, w - 20, sp);
    }
  };

  P.hazard = (ctx, x, y, w, h, color) => {
    ctx.save();
    ctx.beginPath(); ctx.rect(x, y, w, h); ctx.clip();
    ctx.fillStyle = '#121212';
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = color || '#e8701c';
    for (let i = -h; i < w + h; i += 22) {
      ctx.beginPath();
      ctx.moveTo(x + i, y + h);
      ctx.lineTo(x + i + 11, y + h);
      ctx.lineTo(x + i + 11 + h, y);
      ctx.lineTo(x + i + h, y);
      ctx.fill();
    }
    ctx.restore();
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(x, y, w, h);
  };

  P.vents = (ctx, x, y, w, h, n) => {
    ctx.fillStyle = '#08090a';
    const step = w / n;
    for (let i = 0; i < n; i++) {
      U.roundRect(ctx, x + i * step + 2, y, step - 4, h, 2);
      ctx.fill();
    }
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    for (let i = 0; i < n; i++) {
      ctx.beginPath(); ctx.moveTo(x + i * step + 3, y + h + 1); ctx.lineTo(x + (i + 1) * step - 3, y + h + 1); ctx.stroke();
    }
  };

  // Glowing neon bar (baked into sprites with shadowBlur; cheap at runtime because it's cached).
  P.neon = (ctx, x1, y1, x2, y2, w, color) => {
    ctx.save();
    ctx.lineCap = 'round';
    ctx.shadowColor = color;
    ctx.shadowBlur = 18;
    ctx.strokeStyle = color;
    ctx.lineWidth = w;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = 'rgba(255,235,200,0.9)';
    ctx.lineWidth = Math.max(1, w * 0.35);
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    ctx.restore();
  };

  P.glowText = (ctx, text, x, y, size, color, o) => {
    o = o || {};
    ctx.save();
    ctx.font = `${o.weight || ''} ${size}px ${o.font || P.FONT_STENCIL}`.trim();
    ctx.textAlign = o.align || 'center';
    ctx.textBaseline = 'middle';
    if (o.glow !== false) {
      ctx.shadowColor = o.glowColor || color;
      ctx.shadowBlur = o.blur || 22;
    }
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
    ctx.shadowBlur = 0;
    if (o.core) {
      ctx.fillStyle = o.core;
      ctx.fillText(text, x, y);
    }
    ctx.restore();
  };

  P.stencil = (ctx, text, x, y, size, color, align, maxW) => {
    ctx.save();
    if (maxW) U.fitFont(ctx, text, maxW, size, P.FONT_STENCIL);
    else ctx.font = `${size}px ${P.FONT_STENCIL}`;
    ctx.textAlign = align || 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillText(text, x + 2, y + 2);
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
    ctx.restore();
  };

  P.skull = (ctx, cx, cy, s, fill, eye) => {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(s / 100, s / 100);
    ctx.fillStyle = fill;
    ctx.beginPath();
    ctx.moveTo(-42, 4);
    ctx.bezierCurveTo(-48, -50, 48, -50, 42, 4);
    ctx.bezierCurveTo(40, 18, 30, 22, 28, 30);
    ctx.lineTo(28, 46);
    ctx.lineTo(-28, 46);
    ctx.lineTo(-28, 30);
    ctx.bezierCurveTo(-30, 22, -40, 18, -42, 4);
    ctx.fill();
    // eyes / nose / teeth cut-outs
    ctx.fillStyle = eye || '#0b0b0c';
    ctx.beginPath(); ctx.ellipse(-17, 2, 12, 13, 0.2, 0, 6.283); ctx.fill();
    ctx.beginPath(); ctx.ellipse(17, 2, 12, 13, -0.2, 0, 6.283); ctx.fill();
    ctx.beginPath(); ctx.moveTo(0, 14); ctx.lineTo(-6, 26); ctx.lineTo(6, 26); ctx.closePath(); ctx.fill();
    ctx.fillRect(-18, 34, 36, 3);
    for (let i = -14; i <= 14; i += 9.3) ctx.fillRect(i - 1, 30, 2.5, 16);
    ctx.restore();
  };

  // Crossed-rifles-and-skull insignia medallion.
  P.insignia = (ctx, cx, cy, r, accent) => {
    ctx.save();
    ctx.fillStyle = '#0c0d0f';
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, 6.283); ctx.fill();
    ctx.strokeStyle = '#2c3036';
    ctx.lineWidth = 6;
    ctx.stroke();
    ctx.lineWidth = 3;
    ctx.shadowColor = accent; ctx.shadowBlur = 16;
    ctx.strokeStyle = accent;
    ctx.beginPath(); ctx.arc(cx, cy, r - 7, 0, 6.283); ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = '#9aa0a8';
    ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(cx - r * 0.6, cy + r * 0.55); ctx.lineTo(cx + r * 0.6, cy - r * 0.55); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx + r * 0.6, cy + r * 0.55); ctx.lineTo(cx - r * 0.6, cy - r * 0.55); ctx.stroke();
    P.skull(ctx, cx, cy - 2, r * 1.05, '#e9e4da');
    ctx.restore();
  };

  P.wheel = (ctx, cx, cy, r, ang, speed) => {
    ctx.fillStyle = '#0b0c0d';
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, 6.283); ctx.fill();
    ctx.strokeStyle = '#3c4148';
    ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(cx, cy, r - 3, 0, 6.283); ctx.stroke();
    ctx.fillStyle = '#23272c';
    ctx.beginPath(); ctx.arc(cx, cy, r - 7, 0, 6.283); ctx.fill();
    // spokes; ghosted copies fake rotational motion blur at speed
    const ghosts = speed > 260 ? 3 : 1;
    for (let gI = 0; gI < ghosts; gI++) {
      ctx.globalAlpha = ghosts > 1 ? 0.45 : 1;
      const a0 = ang - gI * 0.12;
      ctx.strokeStyle = '#5b626b';
      ctx.lineWidth = 3;
      for (let k = 0; k < 6; k++) {
        const a = a0 + (k * Math.PI) / 3;
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(a) * 6, cy + Math.sin(a) * 6);
        ctx.lineTo(cx + Math.cos(a) * (r - 8), cy + Math.sin(a) * (r - 8));
        ctx.stroke();
      }
    }
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#ff7a1a';
    ctx.beginPath(); ctx.arc(cx, cy, 4, 0, 6.283); ctx.fill();
    // rim highlight
    ctx.strokeStyle = 'rgba(255,140,60,0.35)';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(cx, cy, r - 1, Math.PI * 1.1, Math.PI * 1.6); ctx.stroke();
  };

  P.bogie = (ctx, cx, ang, speed) => {
    const y = P.WHEEL_Y, r = P.WHEEL_R;
    P.wheel(ctx, cx - 38, y, r, ang, speed);
    P.wheel(ctx, cx + 38, y, r, ang + 0.7, speed);
    // side frame + leaf spring
    ctx.fillStyle = '#16191c';
    U.roundRect(ctx, cx - 74, y - 12, 148, 22, 6); ctx.fill();
    ctx.strokeStyle = '#3a3f46'; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.fillStyle = '#2b2f35';
    for (let i = 0; i < 3; i++) { U.roundRect(ctx, cx - 22, y - 26 + i * 5, 44, 4, 2); ctx.fill(); }
    ctx.fillStyle = '#0b0c0d';
    ctx.beginPath(); ctx.arc(cx - 38, y, 7, 0, 6.283); ctx.arc(cx + 38, y, 7, 0, 6.283); ctx.fill();
  };

  // Barrel drawn along +x from the pivot. `heat` 0..1 lights the energy coils.
  P.barrel = (ctx, len, thick, recoil, o) => {
    o = o || {};
    const x0 = -thick * 0.6 - recoil;
    const g = ctx.createLinearGradient(0, -thick / 2, 0, thick / 2);
    g.addColorStop(0, '#6d747d');
    g.addColorStop(0.35, '#2e3338');
    g.addColorStop(1, '#0f1113');
    ctx.fillStyle = g;
    // tapered tube
    ctx.beginPath();
    ctx.moveTo(x0, -thick / 2);
    ctx.lineTo(x0 + len, -thick * 0.36);
    ctx.lineTo(x0 + len, thick * 0.36);
    ctx.lineTo(x0, thick / 2);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.8)'; ctx.lineWidth = 1.5; ctx.stroke();
    // muzzle brake
    ctx.fillStyle = '#1b1e22';
    U.roundRect(ctx, x0 + len - thick * 0.2, -thick * 0.55, thick * 0.9, thick * 1.1, 3); ctx.fill();
    ctx.fillStyle = '#060707';
    ctx.fillRect(x0 + len + thick * 0.05, -thick * 0.55, thick * 0.12, thick * 1.1);
    ctx.fillRect(x0 + len + thick * 0.35, -thick * 0.55, thick * 0.12, thick * 1.1);
    // coils / bands
    const coils = o.coils || 0;
    for (let i = 0; i < coils; i++) {
      const cx = x0 + len * (0.25 + (i * 0.5) / Math.max(1, coils));
      ctx.fillStyle = '#121416';
      ctx.fillRect(cx, -thick * 0.56, thick * 0.35, thick * 1.12);
      if (o.heat > 0.01) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.fillStyle = `rgba(255,${120 + 80 * o.heat | 0},40,${o.heat})`;
        ctx.shadowColor = '#ff7a1a';
        ctx.shadowBlur = 20 * o.heat;
        ctx.fillRect(cx + 2, -thick * 0.5, thick * 0.35 - 4, thick);
        ctx.restore();
      }
    }
    // hot glowing barrel tip after firing
    if (o.hot > 0.01) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const hg = ctx.createLinearGradient(x0 + len * 0.6, 0, x0 + len + thick, 0);
      hg.addColorStop(0, 'rgba(255,80,20,0)');
      hg.addColorStop(1, `rgba(255,120,40,${0.8 * o.hot})`);
      ctx.fillStyle = hg;
      ctx.fillRect(x0 + len * 0.6, -thick * 0.45, len * 0.4 + thick, thick * 0.9);
      ctx.restore();
    }
    // top highlight
    ctx.strokeStyle = 'rgba(255,255,255,0.18)';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(x0 + 4, -thick / 2 + 2); ctx.lineTo(x0 + len - 4, -thick * 0.36 + 2); ctx.stroke();
  };

  P.turretDome = (ctx, x, y, r, tone) => {
    ctx.fillStyle = P.metal(ctx, y - r, y + r * 0.4, tone || 0);
    ctx.beginPath();
    ctx.moveTo(x - r, y + r * 0.35);
    ctx.bezierCurveTo(x - r, y - r * 0.9, x + r, y - r * 0.9, x + r, y + r * 0.35);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.85)'; ctx.lineWidth = 2; ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
    ctx.beginPath(); ctx.arc(x, y + r * 0.2, r * 0.82, Math.PI * 1.2, Math.PI * 1.55); ctx.stroke();
    P.rivets(ctx, x - r * 0.7, y + r * 0.2, r * 1.4, r * 0.35, 1.8);
  };

  P.crown = (ctx, cx, cy, s, color) => {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(s / 40, s / 40);
    ctx.fillStyle = color || '#ffc840';
    ctx.beginPath();
    ctx.moveTo(-20, 10); ctx.lineTo(-22, -10); ctx.lineTo(-10, 0); ctx.lineTo(0, -16);
    ctx.lineTo(10, 0); ctx.lineTo(22, -10); ctx.lineTo(20, 10); ctx.closePath();
    ctx.fill();
    ctx.fillRect(-20, 11, 40, 6);
    ctx.fillStyle = '#ff3b1f';
    ctx.beginPath(); ctx.arc(0, 4, 3.2, 0, 6.283); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    ctx.beginPath(); ctx.arc(-22, -11, 2.5, 0, 6.283); ctx.arc(0, -17, 2.5, 0, 6.283); ctx.arc(22, -11, 2.5, 0, 6.283); ctx.fill();
    ctx.restore();
  };

  P.chevrons = (ctx, cx, cy, s, n, color) => {
    ctx.save();
    ctx.strokeStyle = color || '#ffc840';
    ctx.lineWidth = s * 0.22;
    ctx.lineJoin = 'miter';
    for (let i = 0; i < n; i++) {
      const y = cy - s * 0.3 + i * s * 0.32 - (n - 1) * s * 0.16;
      ctx.beginPath(); ctx.moveTo(cx - s * 0.45, y + s * 0.3); ctx.lineTo(cx, y); ctx.lineTo(cx + s * 0.45, y + s * 0.3); ctx.stroke();
    }
    ctx.restore();
  };

  P.star = (ctx, cx, cy, r, color) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI / 2 + (i * Math.PI) / 5, rr = i % 2 ? r * 0.45 : r;
      ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
    }
    ctx.closePath();
    ctx.fill();
  };

  P.flag = (ctx, x, yTop, poleH, w, h, t, accent) => {
    ctx.fillStyle = '#2a2d31';
    ctx.fillRect(x - 2, yTop, 4, poleH);
    ctx.fillStyle = '#ff7a1a';
    ctx.beginPath(); ctx.arc(x, yTop, 4, 0, 6.283); ctx.fill();
    // waving cloth (flows backward = left, since the train moves right)
    const seg = 14;
    ctx.save();
    ctx.beginPath();
    for (let i = 0; i <= seg; i++) {
      const u = i / seg, px = x - u * w, py = yTop + 6 + Math.sin(t * 9 - u * 5) * 6 * u;
      i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    }
    for (let i = seg; i >= 0; i--) {
      const u = i / seg, px = x - u * w, py = yTop + 6 + h + Math.sin(t * 9 - u * 5 + 0.4) * 6 * u;
      ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = '#121314';
    ctx.fill();
    ctx.clip();
    ctx.fillStyle = accent || '#c0261a';
    ctx.fillRect(x - w, yTop + 6 + h - 8, w, 4);
    ctx.restore();
    P.skull(ctx, x - w * 0.5, yTop + 6 + h * 0.5 + Math.sin(t * 9 - 2.5) * 3, h * 0.55, '#d9d4ca', '#121314');
  };

  P.chain = (ctx, x1, y1, x2, y2, sag) => {
    const n = Math.max(4, Math.round(Math.hypot(x2 - x1, y2 - y1) / 9));
    ctx.strokeStyle = '#6f6a5e';
    ctx.lineWidth = 2;
    for (let i = 0; i < n; i++) {
      const u = (i + 0.5) / n, px = U.lerp(x1, x2, u), py = U.lerp(y1, y2, u) + Math.sin(u * Math.PI) * sag;
      ctx.beginPath();
      if (i % 2) ctx.ellipse(px, py, 5, 2.4, 0, 0, 6.283);
      else ctx.ellipse(px, py, 4.5, 1.2, 0, 0, 6.283);
      ctx.stroke();
    }
  };

  P.crate = (ctx, x, y, w, h, label, tone) => {
    ctx.fillStyle = tone === 'olive' ? '#4a4a32' : '#3b3426';
    ctx.fillRect(x, y, w, h);
    ctx.strokeStyle = 'rgba(0,0,0,0.8)'; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
    ctx.strokeStyle = 'rgba(0,0,0,0.45)'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + w, y + h); ctx.moveTo(x + w, y); ctx.lineTo(x, y + h); ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,0.08)'; ctx.fillRect(x, y, w, 3);
    if (label) {
      ctx.fillStyle = '#1a1712';
      ctx.fillRect(x + w * 0.15, y + h * 0.32, w * 0.7, h * 0.36);
      P.stencil(ctx, label, x + w / 2, y + h / 2 + 1, Math.min(14, h * 0.28), '#e0b25a');
    }
  };

  P.shells = (ctx, x, y, n) => {
    for (let i = 0; i < n; i++) {
      const sx = x + i * 11;
      const g = ctx.createLinearGradient(sx, 0, sx + 9, 0);
      g.addColorStop(0, '#7a5a22'); g.addColorStop(0.4, '#d9a441'); g.addColorStop(1, '#5a3f14');
      ctx.fillStyle = g;
      ctx.fillRect(sx, y - 26, 9, 26);
      ctx.fillStyle = '#2a2d31';
      ctx.beginPath(); ctx.moveTo(sx, y - 26); ctx.lineTo(sx + 4.5, y - 38); ctx.lineTo(sx + 9, y - 26); ctx.fill();
    }
  };

  P.sandbags = (ctx, x, y, w) => {
    for (let row = 0; row < 2; row++) {
      for (let px = x + (row ? 16 : 0); px < x + w - 20; px += 34) {
        const g = ctx.createLinearGradient(0, y - row * 14 - 14, 0, y - row * 14);
        g.addColorStop(0, '#6d6447'); g.addColorStop(1, '#3a3526');
        ctx.fillStyle = g;
        U.roundRect(ctx, px, y - row * 14 - 15, 34, 15, 7);
        ctx.fill();
        ctx.strokeStyle = 'rgba(0,0,0,0.5)'; ctx.lineWidth = 1; ctx.stroke();
      }
    }
  };

  P.glowSprite = (ctx, spr, x, y, size, alpha) => {
    if (alpha <= 0.01) return;
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = Math.min(1, alpha);
    ctx.drawImage(spr, x - size / 2, y - size / 2, size, size);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
  };

  // Weathering pass, painted on top of a finished wagon sprite (only where armor already exists):
  // fire-lit top, ambient occlusion, grime, rust streaks, scratches, grain and bullet holes.
  P.weather = (x, w, seed, o) => {
    o = o || {};
    const r = U.rng(seed), top = 480, bot = 905;
    x.save();
    x.globalCompositeOperation = 'source-atop';
    let g = x.createLinearGradient(0, 560, 0, 900);
    g.addColorStop(0, 'rgba(255,140,60,0.13)');
    g.addColorStop(0.45, 'rgba(0,0,0,0)');
    g.addColorStop(1, 'rgba(0,0,0,0.38)');
    x.fillStyle = g; x.fillRect(-60, top, w + 120, bot - top);
    g = x.createLinearGradient(0, 0, w, 0);
    g.addColorStop(0, 'rgba(0,0,0,0.28)'); g.addColorStop(0.45, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,0.16)');
    x.fillStyle = g; x.fillRect(-60, top, w + 120, bot - top);
    for (let i = 0; i < w / 14; i++) {
      const cx = r() * w, cy = 600 + r() * 280, rr = 20 + r() * 50;
      const rg = x.createRadialGradient(cx, cy, 0, cx, cy, rr);
      rg.addColorStop(0, `rgba(${r() < 0.3 ? '60,35,18' : '6,5,4'},${0.12 + r() * 0.16})`); rg.addColorStop(1, 'rgba(0,0,0,0)');
      x.fillStyle = rg; x.fillRect(cx - rr, cy - rr, rr * 2, rr * 2);
    }
    for (let i = 0; i < w / 20; i++) {
      const sx = r() * w, sy = 620 + r() * 230, len = 18 + r() * 70;
      const sg = x.createLinearGradient(0, sy, 0, sy + len);
      sg.addColorStop(0, `rgba(140,66,24,${0.35 + r() * 0.25})`); sg.addColorStop(1, 'rgba(140,66,24,0)');
      x.fillStyle = sg; x.fillRect(sx, sy, 1.2 + r() * 3, len);
    }
    x.strokeStyle = 'rgba(210,214,220,0.16)';
    x.lineWidth = 0.8;
    for (let i = 0; i < w / 7; i++) {
      const sx = r() * w, sy = 620 + r() * 240, a = (r() - 0.5) * 0.8, l = 4 + r() * 16;
      x.beginPath(); x.moveTo(sx, sy); x.lineTo(sx + Math.cos(a) * l, sy + Math.sin(a) * l); x.stroke();
    }
    for (let i = 0; i < w * 6; i++) {
      x.fillStyle = r() < 0.5 ? 'rgba(255,255,255,0.045)' : 'rgba(0,0,0,0.09)';
      x.fillRect(r() * w, top + r() * (bot - top), 1.5, 1.5);
    }
    for (let i = 0; i < (o.holes || 0); i++) {
      const cx = 30 + r() * (w - 60), cy = 700 + r() * 150, hr = 2.5 + r() * 3;
      x.strokeStyle = 'rgba(0,0,0,0.6)'; x.lineWidth = 1;
      for (let k = 0; k < 5; k++) { const a = r() * 6.283; x.beginPath(); x.moveTo(cx, cy); x.lineTo(cx + Math.cos(a) * hr * 3, cy + Math.sin(a) * hr * 3); x.stroke(); }
      x.fillStyle = 'rgba(150,150,150,0.18)'; x.beginPath(); x.arc(cx - 0.6, cy - 0.6, hr + 1.2, 0, 6.283); x.fill();
      x.fillStyle = '#050505'; x.beginPath(); x.arc(cx, cy, hr * 0.8, 0, 6.283); x.fill();
      if (r() < 0.15) { x.fillStyle = 'rgba(255,110,30,0.35)'; x.beginPath(); x.arc(cx, cy, hr * 0.45, 0, 6.283); x.fill(); }
    }
    x.restore();
  };

  WT.P = P;
})(window.WT);

/* ---- js/fx/strikes.js ---- */
/* War Train — SUB BOMB killstreaks. Big gifts call in a cinematic strike while the gifter's cannon
   wagon is on screen. Coordinates are design pixels in "train space" (see Run.TRAIN_SCALE).
     REINFORCEMENTS (1+)  card only
     PRECISION AIRSTRIKE (5+)  jet formation fires missiles into the horizon
     CHOPPER GUNNER (10+)      attack helicopter strafes with minigun + rockets
     CARPET BOMBING (25+)      heavy bomber lays a wall of explosions
     TACTICAL NUKE (50+)       countdown, white-out, shockwave and mushroom cloud */
window.WT = window.WT || {};
(function (WT) {
  'use strict';
  const U = WT.U, P = WT.P;
  const ACCENT = '#ff7a1a', GOLD = '#ffc840', RED = '#ff2a1a';
  const GROUND = 936; // where ground impacts happen (just behind the rail)

  WT.killstreakFor = function (count) {
    const list = (WT.cfg.killstreaks || []).slice().sort((a, b) => b.min - a.min);
    for (const k of list) if (count >= k.min) return k;
    return { min: 1, kind: 'supply', label: 'REINFORCEMENTS', extra: 0 };
  };

  // ------------------------------------------------------------ aircraft art --
  function drawJet(ctx, x, y, s, t) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    // afterburner
    const ab = 0.8 + 0.2 * Math.sin(t * 60);
    P.glowSprite(ctx, WT.sprites.orange, -92, 1, 90 * ab, 0.9);
    P.glowSprite(ctx, WT.sprites.hot, -88, 1, 36 * ab, 1);
    ctx.globalCompositeOperation = 'lighter';
    const cone = ctx.createLinearGradient(-86, 0, -150, 0);
    cone.addColorStop(0, 'rgba(255,190,110,0.9)'); cone.addColorStop(1, 'rgba(255,90,30,0)');
    ctx.fillStyle = cone;
    ctx.beginPath(); ctx.moveTo(-84, -4); ctx.lineTo(-150 - 10 * ab, 1); ctx.lineTo(-84, 6); ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
    // far wing (darker)
    ctx.fillStyle = '#16191c';
    ctx.beginPath(); ctx.moveTo(14, -4); ctx.lineTo(-22, -4); ctx.lineTo(-44, -20); ctx.lineTo(-30, -20); ctx.fill();
    // fuselage
    const g = ctx.createLinearGradient(0, -10, 0, 10);
    g.addColorStop(0, '#6a7079'); g.addColorStop(0.45, '#33383e'); g.addColorStop(1, '#121417');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(100, 2); ctx.lineTo(62, -7); ctx.lineTo(-40, -9); ctx.lineTo(-80, -5); ctx.lineTo(-84, 5); ctx.lineTo(-40, 9); ctx.lineTo(62, 8); ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.7)'; ctx.lineWidth = 1; ctx.stroke();
    // intake + canopy
    ctx.fillStyle = '#0b0c0d'; ctx.fillRect(8, 1, 26, 6);
    const cg = ctx.createLinearGradient(30, -14, 60, -6);
    cg.addColorStop(0, 'rgba(255,170,80,0.85)'); cg.addColorStop(1, 'rgba(40,30,30,0.9)');
    ctx.fillStyle = cg;
    ctx.beginPath(); ctx.ellipse(46, -8, 18, 5, -0.06, Math.PI, 0); ctx.fill();
    // near wing, tail, stabiliser
    ctx.fillStyle = '#2a2e33';
    ctx.beginPath(); ctx.moveTo(18, 3); ctx.lineTo(-28, 3); ctx.lineTo(-58, 22); ctx.lineTo(-38, 22); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(-50, -8); ctx.lineTo(-76, -36); ctx.lineTo(-88, -36); ctx.lineTo(-80, -6); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(-60, 5); ctx.lineTo(-86, 13); ctx.lineTo(-94, 13); ctx.lineTo(-82, 3); ctx.closePath(); ctx.fill();
    // missiles under the wing + nav light
    ctx.fillStyle = '#4b5057'; ctx.fillRect(-26, 23, 30, 3);
    if (Math.sin(t * 14) > 0.3) P.glowSprite(ctx, WT.sprites.red, -56, 22, 26, 1);
    ctx.restore();
  }

  function drawHeli(ctx, x, y, s, t, tilt) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(tilt || 0);
    ctx.scale(s, s);
    // tail boom + fin + tail rotor
    ctx.fillStyle = '#1e2226';
    ctx.beginPath(); ctx.moveTo(-30, -10); ctx.lineTo(-150, -14); ctx.lineTo(-150, -6); ctx.lineTo(-30, 8); ctx.fill();
    ctx.beginPath(); ctx.moveTo(-138, -12); ctx.lineTo(-160, -44); ctx.lineTo(-168, -44); ctx.lineTo(-156, -8); ctx.fill();
    ctx.strokeStyle = 'rgba(160,165,170,0.35)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(-160, -26, 16, 0, 6.283); ctx.stroke();
    const ta = t * 50;
    ctx.strokeStyle = '#555b62'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-160 + Math.cos(ta) * 16, -26 + Math.sin(ta) * 16); ctx.lineTo(-160 - Math.cos(ta) * 16, -26 - Math.sin(ta) * 16); ctx.stroke();
    // body
    const g = ctx.createLinearGradient(0, -34, 0, 30);
    g.addColorStop(0, '#5c636b'); g.addColorStop(0.4, '#2c3136'); g.addColorStop(1, '#0f1113');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(70, 10); ctx.quadraticCurveTo(76, -18, 40, -28); ctx.lineTo(-20, -32); ctx.quadraticCurveTo(-46, -24, -46, 0);
    ctx.quadraticCurveTo(-44, 22, -10, 26); ctx.lineTo(50, 24); ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.7)'; ctx.lineWidth = 1.5; ctx.stroke();
    // canopy glass with warm reflection
    const cg = ctx.createLinearGradient(20, -26, 66, 4);
    cg.addColorStop(0, 'rgba(255,170,80,0.75)'); cg.addColorStop(1, 'rgba(30,25,25,0.95)');
    ctx.fillStyle = cg;
    ctx.beginPath(); ctx.moveTo(66, 4); ctx.quadraticCurveTo(68, -16, 38, -24); ctx.lineTo(24, -22); ctx.lineTo(28, 2); ctx.closePath(); ctx.fill();
    // stub wing + rocket pod + minigun
    ctx.fillStyle = '#16191c'; ctx.fillRect(-18, 6, 40, 6);
    ctx.fillStyle = '#2a2e33'; U.roundRect(ctx, -14, 12, 34, 12, 5); ctx.fill();
    ctx.fillStyle = '#ff3b1f'; ctx.fillRect(18, 15, 3, 6);
    ctx.fillStyle = '#0c0d0f'; ctx.fillRect(60, 20, 26, 5);
    // skids
    ctx.strokeStyle = '#121416'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-30, 26); ctx.lineTo(-30, 36); ctx.moveTo(30, 24); ctx.lineTo(30, 36); ctx.moveTo(-50, 36); ctx.lineTo(50, 36); ctx.stroke();
    // rotor mast + blurred main rotor
    ctx.fillStyle = '#121416'; ctx.fillRect(-6, -44, 12, 14);
    ctx.fillStyle = 'rgba(120,125,130,0.18)';
    ctx.beginPath(); ctx.ellipse(0, -44, 150, 9, 0, 0, 6.283); ctx.fill();
    const ra = t * 32;
    ctx.strokeStyle = 'rgba(40,44,48,0.85)'; ctx.lineWidth = 4;
    for (let i = 0; i < 2; i++) {
      const c = Math.cos(ra + i * Math.PI / 2) * 150;
      ctx.beginPath(); ctx.moveTo(-c, -44); ctx.lineTo(c, -44); ctx.stroke();
    }
    if (Math.sin(t * 12) > 0.4) P.glowSprite(ctx, WT.sprites.red, -150, -10, 24, 1);
    ctx.restore();
  }

  function drawBomber(ctx, x, y, s, t, bayOpen) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    for (const ex of [-10, 60]) {
      P.glowSprite(ctx, WT.sprites.orange, ex - 50, 14, 50, 0.5 + 0.2 * Math.sin(t * 40 + ex));
    }
    const g = ctx.createLinearGradient(0, -18, 0, 18);
    g.addColorStop(0, '#5a6068'); g.addColorStop(0.5, '#2a2e33'); g.addColorStop(1, '#101214');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(190, 4); ctx.quadraticCurveTo(186, -14, 150, -16); ctx.lineTo(-170, -14); ctx.lineTo(-210, -8); ctx.lineTo(-212, 6); ctx.lineTo(-170, 14); ctx.lineTo(150, 16); ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.7)'; ctx.lineWidth = 1.5; ctx.stroke();
    // tail fin
    ctx.fillStyle = '#25292e';
    ctx.beginPath(); ctx.moveTo(-150, -14); ctx.lineTo(-196, -78); ctx.lineTo(-218, -78); ctx.lineTo(-200, -8); ctx.closePath(); ctx.fill();
    // wing + engine pods
    ctx.fillStyle = '#1b1e22';
    ctx.beginPath(); ctx.moveTo(70, -6); ctx.lineTo(-40, -6); ctx.lineTo(-120, 12); ctx.lineTo(-60, 12); ctx.closePath(); ctx.fill();
    for (const ex of [-10, 60]) { ctx.fillStyle = '#2d3237'; U.roundRect(ctx, ex - 46, 8, 46, 12, 6); ctx.fill(); ctx.fillStyle = '#0a0a0b'; ctx.fillRect(ex - 2, 9, 3, 10); }
    // cockpit windows
    ctx.fillStyle = 'rgba(255,160,70,0.8)'; ctx.fillRect(150, -12, 22, 5);
    // bomb bay
    if (bayOpen) { ctx.fillStyle = '#050505'; ctx.fillRect(-60, 12, 110, 6); P.glowSprite(ctx, WT.sprites.red, 0, 18, 60, 0.4); }
    ctx.restore();
  }

  // Continuous vapour trail behind an aircraft: thin and bright at the engine, wide and faint behind.
  function drawContrail(ctx, x, y, len, alpha) {
    if (alpha <= 0 || x < -200) return;
    const x0 = x - len, g = ctx.createLinearGradient(x, 0, x0, 0);
    g.addColorStop(0, `rgba(225,228,232,${0.55 * alpha})`);
    g.addColorStop(0.4, `rgba(200,204,210,${0.22 * alpha})`);
    g.addColorStop(1, 'rgba(200,204,210,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(x, y - 1.5); ctx.lineTo(x0, y - 14); ctx.lineTo(x0, y + 14); ctx.lineTo(x, y + 1.5);
    ctx.closePath();
    ctx.fill();
  }

  function drawTrefoil(ctx, x, y, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, r * 0.18, 0, 6.283); ctx.fill();
    for (let i = 0; i < 3; i++) {
      const a = -Math.PI / 2 + i * (2 * Math.PI / 3);
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(a - 0.5) * r * 0.28, y + Math.sin(a - 0.5) * r * 0.28);
      ctx.arc(x, y, r, a - 0.5, a + 0.5);
      ctx.arc(x, y, r * 0.28, a + 0.5, a - 0.5, true);
      ctx.fill();
    }
  }

  function drawIcon(ctx, kind, x, y, t) {
    if (kind === 'airstrike') drawJet(ctx, x + 6, y + 4, 0.48, t);
    else if (kind === 'chopper') drawHeli(ctx, x + 14, y + 12, 0.32, t, 0);
    else if (kind === 'carpet') {
      ctx.save(); ctx.translate(x, y); ctx.rotate(0.6);
      ctx.fillStyle = '#d9d3c4'; U.roundRect(ctx, -12, -30, 24, 50, 12); ctx.fill();
      ctx.beginPath(); ctx.moveTo(-14, 18); ctx.lineTo(14, 18); ctx.lineTo(18, 32); ctx.lineTo(-18, 32); ctx.fill();
      ctx.fillStyle = RED; ctx.fillRect(-12, -6, 24, 5);
      ctx.restore();
    } else if (kind === 'nuke') {
      ctx.fillStyle = '#ffd23a'; ctx.beginPath(); ctx.arc(x, y, 38, 0, 6.283); ctx.fill();
      drawTrefoil(ctx, x, y, 32, '#111');
    } else {
      // supply crate on a parachute
      ctx.strokeStyle = '#cfc8b8'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(x - 24, y - 16); ctx.lineTo(x - 10, y + 8); ctx.moveTo(x + 24, y - 16); ctx.lineTo(x + 10, y + 8); ctx.stroke();
      ctx.fillStyle = ACCENT; ctx.beginPath(); ctx.arc(x, y - 16, 26, Math.PI, 0); ctx.fill();
      P.crate(ctx, x - 14, y + 6, 28, 22, '', 'olive');
    }
  }

  // ------------------------------------------------------------- strikes --
  class Strike {
    constructor(mgr, g, t0, ks) {
      this.mgr = mgr; this.fx = mgr.fx; this.g = g; this.t0 = t0; this.ks = ks;
      this.dur = 3; this.fired = {}; this.acc = {};
    }
    once(key, cond, fn) { if (cond && !this.fired[key]) { this.fired[key] = true; fn(); } }
    every(key, rate, dt, fn) { this.acc[key] = (this.acc[key] || 0) + rate * dt; while (this.acc[key] >= 1) { this.acc[key] -= 1; fn(); } }
    get done() { return false; }
    update() {}
    drawBack() {}
    drawHud() {}
  }

  class Supply extends Strike {
    constructor(m, g, t0, ks) { super(m, g, t0, ks); this.dur = 2.6; }
  }

  class Airstrike extends Strike {
    constructor(m, g, t0, ks) {
      super(m, g, t0, ks);
      this.dur = 3.4;
      this.jets = [{ y: 290, dx: 0 }, { y: 330, dx: -170 }, { y: 360, dx: -330 }];
    }
    jetX(j, t) { return -260 + j.dx + (t - this.t0 - 0.25) * 2500; }
    update(t, dt) {
      const fx = this.fx, lt = t - this.t0;
      this.once('snd', lt > 0.1, () => this.mgr.sound.play('jet'));
      this.jets.forEach((j, i) => {
        const x = this.jetX(j, t);
        [380 + i * 140, 820 + i * 160].forEach((lx, k) => {
          this.once(`m${i}${k}`, x >= lx, () => {
            fx.missile(x + 10, j.y + 24, lx + 420 + fx.r(-60, 60), GROUND, { life: 0.5, end: 'ground', scale: 0.95, endLayer: 'back' });
            this.mgr.sound.play('clank', { gain: 0.5 });
          });
        });
      });
      this.once('boom', lt > 0.9, () => this.mgr.sound.play('explosion'));
    }
    drawBack(ctx, t) {
      const fade = 1 - U.inv(this.dur - 1.2, this.dur, t - this.t0);
      for (const j of this.jets) {
        const x = this.jetX(j, t);
        drawContrail(ctx, Math.min(x, 2400) - 100, j.y + 2, 1700, fade);
        if (x > -300 && x < 2300) drawJet(ctx, x, j.y, 1.2, t);
      }
    }
  }

  class Chopper extends Strike {
    constructor(m, g, t0, ks) { super(m, g, t0, ks); this.dur = 4.2; }
    pos(t) {
      const lt = t - this.t0;
      if (lt < 0.9) { const k = U.easeOutCubic(lt / 0.9); return { x: U.lerp(2150, 1500, k), y: U.lerp(330, 390, k), tilt: 0.12 * (1 - k) - 0.1 }; }
      if (lt < 3.2) { const k = (lt - 0.9) / 2.3; return { x: U.lerp(1500, 1120, k), y: 390 + Math.sin(lt * 3) * 8, tilt: -0.14 }; }
      const k = U.easeInCubic(Math.min(1, (lt - 3.2) / 1.0));
      return { x: U.lerp(1120, 2250, k), y: U.lerp(390, 230, k), tilt: 0.05 + 0.15 * k };
    }
    muzzle(p) { return { x: p.x + Math.cos(p.tilt) * 92 - Math.sin(p.tilt) * 30, y: p.y + Math.sin(p.tilt) * 92 + Math.cos(p.tilt) * 30 }; }
    update(t, dt) {
      const fx = this.fx, lt = t - this.t0, p = this.pos(t);
      this.once('snd', lt > 0, () => this.mgr.sound.play('chopper', { duration: this.dur }));
      if (lt > 1.0 && lt < 3.1) {
        this.once('gun', true, () => this.mgr.sound.play('minigun', { duration: 2.1 }));
        const tx = U.lerp(1350, 520, (lt - 1.0) / 2.1);
        this.every('mg', 26, dt, () => {
          const m = this.muzzle(p), ax = tx + fx.r(-40, 40) - m.x, ay = GROUND - m.y;
          fx.tracer(m.x, m.y, Math.atan2(ay, ax), { speed: 2800, len: 120, life: Math.hypot(ax, ay) / 2800, color: '255,200,110' });
          fx.flash(m.x, m.y, 40, Math.atan2(ay, ax), { life: 0.04 });
        });
        this.every('hit', 9, dt, () => {
          const x = tx + fx.r(-50, 50);
          fx.sparks(x, GROUND - 6, { n: 8, angle: -1.9, spread: 0.7, speed: 420 });
          fx.smoke(x, GROUND - 10, { n: 1, kind: 'warm', size: 40, alpha: 0.5, vy: -40, life: 1.2 });
          fx.flash(x, GROUND - 10, 70, 0, { life: 0.06, layer: 'back' });
        });
      }
      [1.7, 2.4].forEach((rt, i) => this.once('r' + i, lt >= rt, () => {
        fx.missile(p.x + 10, p.y + 24, U.lerp(1250, 700, i) + fx.r(-60, 60), GROUND, { life: 0.45, end: 'ground', scale: 1.1, endLayer: 'back' });
        this.mgr.sound.play('explosion', { gain: 0.8 });
      }));
    }
    drawBack(ctx, t) {
      const p = this.pos(t), lt = t - this.t0;
      // searchlight sweeping the ground
      const sa = U.envelope(lt, 0.5, 3.4, 0.3, 0.3);
      if (sa > 0) {
        const m = this.muzzle(p), gx = U.lerp(1300, 600, U.clamp((lt - 0.6) / 2.6, 0, 1));
        ctx.globalCompositeOperation = 'lighter';
        const g = ctx.createLinearGradient(m.x, m.y, gx, GROUND);
        g.addColorStop(0, `rgba(255,230,190,${0.32 * sa})`); g.addColorStop(1, 'rgba(255,200,140,0)');
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.moveTo(m.x - 6, m.y); ctx.lineTo(gx - 120, GROUND); ctx.lineTo(gx + 120, GROUND); ctx.lineTo(m.x + 6, m.y); ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
      }
      drawHeli(ctx, p.x, p.y, 1.25, t, p.tilt);
    }
  }

  class CarpetBomb extends Strike {
    constructor(m, g, t0, ks) { super(m, g, t0, ks); this.dur = 4.4; this.y = 300; this.speed = 820; this.nextDrop = 140; }
    bx(t) { return -420 + (t - this.t0) * this.speed; }
    update(t, dt) {
      const fx = this.fx, x = this.bx(t);
      this.once('snd', t - this.t0 > 0.1, () => this.mgr.sound.play('jet', { gain: 0.7 }));
      while (x >= this.nextDrop && this.nextDrop < 1820) {
        const fall = Math.sqrt((2 * (GROUND - this.y - 20)) / 900);
        fx.add({ t: 'bomb', layer: 'back', x: this.nextDrop, y: this.y + 20, vx: this.speed * 0.85, vy: 0, g: 900, drag: 0, life: fall, end: 'ground', scale: 1.15, endLayer: 'back' });
        this.nextDrop += 105;
        if (this.nextDrop % 315 < 105) this.mgr.sound.play('explosion', { gain: 0.6, delay: fall });
      }
    }
    drawBack(ctx, t) {
      const x = this.bx(t), fade = 1 - U.inv(this.dur - 1, this.dur, t - this.t0);
      for (const ex of [-60, 10]) drawContrail(ctx, Math.min(x, 2500) + (ex - 50) * 1.3, this.y + 20, 1400, fade * 0.8);
      if (x > -500 && x < 2400) drawBomber(ctx, x, this.y, 1.3, t, x > 80 && x < 1840);
    }
  }

  class Nuke extends Strike {
    constructor(m, g, t0, ks) {
      super(m, g, t0, ks);
      this.dur = 6.6; this.X = 1380; this.det = 2.4;
    }
    update(t, dt) {
      const fx = this.fx, lt = t - this.t0, d = lt - this.det;
      this.once('siren', lt >= 0, () => this.mgr.sound.play('siren', { duration: 2.4 }));
      this.once('missile', lt >= 1.85, () => fx.add({ t: 'missile', layer: 'back', x: this.X + 160, y: -60, vx: -160 / 0.55, vy: (GROUND + 60) / 0.55, life: 0.55, drag: 0, scale: 1.6 }));
      this.once('det', d >= 0, () => {
        fx.groundBlast(this.X, GROUND, 2.4, { layer: 'back' });
        fx.explosion(this.X, GROUND - 120, 2, { layer: 'back' });
        fx.shake(30, 1.4);
        this.mgr.sound.play('explosion', { gain: 2 });
        this.mgr.sound.play('rumble', { duration: 4, gain: 1.6 });
      });
      if (d > 0 && d < 3.8) {
        const rise = U.easeOutCubic(Math.min(1, d / 2.6)), capY = U.lerp(GROUND - 120, 380, rise);
        const rx = U.lerp(90, 250, rise), ry = rx * 0.42;
        // stem
        this.every('stem', 50 * fx.mult, dt, () => {
          const y = fx.r(capY, GROUND);
          fx.fire(this.X + fx.r(-28, 28) * (1 + (GROUND - y) / 900), y, { n: 1, size: 40, vy: -120, life: 0.9, layer: 'back' });
          if (fx.rnd() < 0.5) fx.smoke(this.X + fx.r(-40, 40), y, { n: 1, kind: 'warm', size: 60, vy: -80, jitter: 20, life: 2.2, alpha: 0.5, layer: 'back' });
        });
        // rolling cap
        this.every('cap', 70 * fx.mult, dt, () => {
          const a = fx.r(0, 6.283), px = this.X + Math.cos(a) * rx, py = capY + Math.sin(a) * ry;
          const roll = Math.sin(a) < 0 ? 1 : -1; // top rolls outward, bottom rolls inward
          fx.smoke(px, py, { n: 1, kind: fx.rnd() < 0.6 ? 'soot' : 'warm', size: fx.r(90, 170), vx: Math.cos(a) * 60 * roll, vy: -30, jitter: 15, life: 2.8, alpha: 1, layer: 'back', grow: 1.5 });
          if (fx.rnd() < 0.35) fx.fire(this.X + Math.cos(a) * rx * 0.5, capY + Math.abs(Math.sin(a)) * ry * 0.5, { n: 1, size: 60, vy: -10, life: 0.8, layer: 'back', g: 0 });
        });
        // dust wall rolling out along the ground
        if (d < 1.6) this.every('dust', 40 * fx.mult, dt, () => {
          const dir = fx.rnd() < 0.5 ? -1 : 1, r = d * 1100;
          fx.smoke(this.X + dir * r, GROUND - fx.r(0, 40), { n: 1, kind: 'warm', size: 110, vx: dir * 300, vy: -20, life: 1.6, alpha: 0.6, layer: 'back' });
        });
        this.every('ash', 25, dt, () => fx.embers(fx.r(0, 1920), fx.r(200, 700), { n: 1, lift: -0.4, spread: 10 }));
      }
    }
    drawBack(ctx, t) {
      const d = t - this.t0 - this.det;
      if (d <= 0) return;
      const rise = U.easeOutCubic(Math.min(1, d / 2.6)), capY = U.lerp(GROUND - 120, 380, rise);
      const fade = 1 - U.inv(2.6, 4.0, d);
      // procedural mushroom body under the particle texture: dark rolling cap with a burning underside
      const rx = U.lerp(90, 250, rise) * 1.25, ry = rx * 0.5, sa = 0.9 * fade;
      const sg = ctx.createLinearGradient(this.X - 70, 0, this.X + 70, 0);
      sg.addColorStop(0, 'rgba(50,30,20,0)'); sg.addColorStop(0.3, `rgba(90,45,22,${0.75 * sa})`);
      sg.addColorStop(0.5, `rgba(255,150,60,${0.85 * sa})`); sg.addColorStop(0.7, `rgba(90,45,22,${0.75 * sa})`); sg.addColorStop(1, 'rgba(50,30,20,0)');
      ctx.fillStyle = sg;
      ctx.beginPath();
      ctx.moveTo(this.X - 34, capY); ctx.lineTo(this.X + 34, capY);
      ctx.lineTo(this.X + 60 + (GROUND - capY) * 0.04, GROUND); ctx.lineTo(this.X - 60 - (GROUND - capY) * 0.04, GROUND); ctx.closePath();
      ctx.fill();
      const cg = ctx.createRadialGradient(this.X, capY + ry * 0.35, 0, this.X, capY, rx);
      cg.addColorStop(0, `rgba(255,180,90,${0.95 * sa})`); cg.addColorStop(0.35, `rgba(200,80,30,${0.85 * sa})`);
      cg.addColorStop(0.75, `rgba(48,26,18,${0.9 * sa})`); cg.addColorStop(1, 'rgba(30,20,16,0)');
      ctx.fillStyle = cg;
      ctx.beginPath(); ctx.ellipse(this.X, capY, rx, ry, 0, 0, 6.283); ctx.fill();
      // skirt ring around the stem
      ctx.fillStyle = `rgba(70,40,26,${0.55 * sa})`;
      ctx.beginPath(); ctx.ellipse(this.X, U.lerp(capY, GROUND, 0.45), rx * 0.5, ry * 0.3, 0, 0, 6.283); ctx.fill();
      // glowing core of the cap + stem
      P.glowSprite(ctx, WT.sprites.orange, this.X, capY, 700 * (0.6 + rise * 0.6), 0.6 * fade);
      P.glowSprite(ctx, WT.sprites.hot, this.X, capY, 260, 0.6 * fade);
      P.glowSprite(ctx, WT.sprites.orange, this.X, GROUND - 60, 900, 0.6 * fade);
      // shockwave ellipse racing along the ground
      if (d < 1.6) {
        const k = d / 1.6, rx = 2400 * U.easeOutCubic(k);
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = `rgba(255,220,170,${0.8 * (1 - k)})`;
        ctx.lineWidth = 16 * (1 - k) + 2;
        ctx.beginPath(); ctx.ellipse(this.X, GROUND - 20, rx, rx * 0.12, 0, 0, 6.283); ctx.stroke();
        ctx.strokeStyle = `rgba(255,160,90,${0.5 * (1 - k)})`;
        ctx.lineWidth = 6;
        ctx.beginPath(); ctx.arc(this.X, GROUND - 120, rx * 0.5, Math.PI, 0); ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
      }
    }
    drawHud(ctx, t) {
      const lt = t - this.t0, d = lt - this.det;
      if (lt < this.det) {
        // red alarm vignette + countdown
        const pulse = 0.5 + 0.5 * Math.sin(lt * 14);
        const g = ctx.createRadialGradient(960, 540, 380, 960, 540, 1150);
        g.addColorStop(0, 'rgba(255,20,10,0)'); g.addColorStop(1, `rgba(255,20,10,${0.25 + 0.25 * pulse})`);
        ctx.fillStyle = g; ctx.fillRect(-100, -100, 2120, 1280);
        const n = Math.max(1, 3 - Math.floor(lt / 0.8)), k = (lt % 0.8) / 0.8;
        ctx.save();
        ctx.globalAlpha = 1 - k * 0.6;
        ctx.translate(960, 290); ctx.scale(1.6 - 0.6 * U.easeOutCubic(k), 1.6 - 0.6 * U.easeOutCubic(k));
        P.glowText(ctx, String(n), 0, 0, 170, RED, { glowColor: RED, core: '#ffd0c8', blur: 40 });
        ctx.restore();
        P.glowText(ctx, 'TACTICAL NUKE INCOMING', 960, 140, 48, RED, { glowColor: RED, core: '#ffe0d8', blur: 18 });
      }
      if (d > 0 && d < 1.2) {
        const k = d / 1.2;
        ctx.fillStyle = `rgba(255,252,240,${0.92 * Math.pow(1 - k, 2)})`;
        ctx.fillRect(-100, -100, 2120, 1280);
      }
      if (d > 0 && d < 3.5) {
        ctx.fillStyle = `rgba(255,110,40,${0.16 * (1 - d / 3.5)})`;
        ctx.fillRect(-100, -100, 2120, 1280);
      }
    }
  }

  const KINDS = { supply: Supply, airstrike: Airstrike, chopper: Chopper, carpet: CarpetBomb, nuke: Nuke };

  class StrikeManager {
    constructor(fx, sound) { this.fx = fx; this.sound = sound; this.list = []; }
    start(g, t0) {
      const ks = WT.killstreakFor(g.giftCount), K = KINDS[ks.kind] || Supply;
      const s = new K(this, g, t0, ks);
      this.list.push(s);
      return s;
    }
    update(t, dt) {
      for (const s of this.list) if (t >= s.t0) s.update(t, dt);
      this.list = this.list.filter((s) => t < s.t0 + s.dur + 0.5);
    }
    drawBack(ctx, t) { for (const s of this.list) if (t >= s.t0) s.drawBack(ctx, t); }
    drawHud(ctx, t) {
      for (const s of this.list) {
        if (t < s.t0) continue;
        s.drawHud(ctx, t);
        this.drawCard(ctx, s, t);
      }
    }
    // CoD-style killstreak card at the top of the screen.
    drawCard(ctx, s, t) {
      const lt = t - s.t0, nuke = s.ks.kind === 'nuke';
      const cardT = nuke ? lt - s.det - 0.4 : lt; // nuke card appears after the white-out
      const a = U.envelope(cardT, 0, 2.9, 0.2, 0.4);
      if (a <= 0) return;
      const w = 820, h = 128, x = 960 - w / 2;
      const y = 120 - (1 - U.easeOutBack(U.inv(0, 0.3, cardT))) * 160;
      const glitch = cardT < 0.25 ? (Math.sin(t * 190) * 14) : 0;
      const col = nuke ? '#ffd23a' : s.ks.kind === 'supply' ? ACCENT : GOLD;
      ctx.save();
      ctx.globalAlpha = a;
      ctx.translate(glitch, 0);
      const bg = ctx.createLinearGradient(x, 0, x + w, 0);
      bg.addColorStop(0, 'rgba(8,8,9,0.94)'); bg.addColorStop(1, 'rgba(20,14,10,0.9)');
      ctx.fillStyle = bg;
      U.chamfer(ctx, x, y, w, h, 14); ctx.fill();
      ctx.save(); ctx.shadowColor = col; ctx.shadowBlur = 20; ctx.strokeStyle = col; ctx.lineWidth = 3; ctx.stroke(); ctx.restore();
      // icon tile
      ctx.fillStyle = 'rgba(255,122,26,0.12)';
      U.chamfer(ctx, x + 10, y + 10, h - 20, h - 20, 10); ctx.fill();
      drawIcon(ctx, s.ks.kind, x + h / 2, y + h / 2, t);
      // texts
      ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
      ctx.font = `600 18px ${P.FONT_UI}`; ctx.fillStyle = '#ffb070';
      const n = s.g.giftCount;
      ctx.fillText(s.ks.kind === 'supply' ? `NEW SUB GIFTER  •  ×${n}` : `SUB BOMB  •  ×${n} GIFTED SUBS`, x + h + 8, y + 34);
      U.fitFont(ctx, s.ks.label, w - h - 30, 54, P.FONT_STENCIL);
      ctx.save(); ctx.shadowColor = col; ctx.shadowBlur = 18; ctx.fillStyle = col; ctx.fillText(s.ks.label, x + h + 8, y + 86); ctx.restore();
      ctx.fillStyle = '#f4efe6';
      U.fitFont(ctx, `CALLED IN BY ${U.cleanName(s.g.username).toUpperCase()}`, w - h - 30, 20, P.FONT_UI, '700');
      ctx.fillText(`CALLED IN BY ${U.cleanName(s.g.username).toUpperCase()}`, x + h + 8, y + 113);
      // scanline sweep
      const sw = U.inv(0, 0.6, cardT);
      if (sw < 1) { ctx.globalCompositeOperation = 'lighter'; ctx.fillStyle = 'rgba(255,170,90,0.25)'; ctx.fillRect(x + w * sw - 40, y, 40, h); }
      ctx.restore();
    }
  }

  WT.StrikeManager = StrikeManager;
  WT.drawJet = drawJet;
  WT.drawHeli = drawHeli;
})(window.WT);

/* ---- js/train/wagons.js ---- */
/* War Train — locomotive and wagon components.
   Static armor is painted once into an offscreen sprite; moving parts (wheels, turrets, barrels,
   lights, flags, nameplates, avatars) are drawn live every frame on top of it. */
window.WT = window.WT || {};
(function (WT) {
  'use strict';
  const U = WT.U, P = WT.P;

  const SPR_TOP = 470, SPR_H = 440, PAD = 60;
  const ACCENT = '#ff7a1a', HOT = '#ff3b1f', GOLD = '#ffc840';

  // ---------------------------------------------------------------- Gun --
  class Gun {
    constructor(o) {
      Object.assign(this, { px: 0, py: 0, len: 150, thick: 22, rest: -0.12, maxRecoil: 22, coils: 0, twin: false, dome: 34, tone: 0, flip: false }, o);
      this.aimKeys = [];     // [{t, a}] angle keyframes (radians, negative = up)
      this.lastFire = -99;
      this.chargeFrom = -99; this.chargeTo = -99;
    }
    aimTo(t0, t1, a) { this.aimKeys.push({ t0, t1, a }); this.aimKeys.sort((x, y) => x.t0 - y.t0); }
    angle(t) {
      let a = this.rest;
      for (const k of this.aimKeys) {
        if (t >= k.t1) a = k.a;
        else if (t > k.t0) { a = U.lerp(a, k.a, U.easeInOut(U.inv(k.t0, k.t1, t))); break; }
        else break;
      }
      return this.flip ? Math.PI - a : a;
    }
    recoil(t) {
      const d = t - this.lastFire;
      if (d < 0 || d > 0.6) return 0;
      return this.maxRecoil * (d < 0.05 ? d / 0.05 : 1 - U.easeOutCubic((d - 0.05) / 0.55));
    }
    heat(t) {
      if (t >= this.chargeFrom && t <= this.chargeTo) return U.inv(this.chargeFrom, this.chargeTo, t);
      const d = t - this.chargeTo;
      return d > 0 && d < 0.5 ? 1 - d / 0.5 : 0;
    }
    hot(t) { const d = t - this.lastFire; return d >= 0 && d < 1.4 ? 1 - d / 1.4 : 0; }
    muzzle(sx, dy, t) {
      const a = this.angle(t), L = this.len - this.thick * 0.6 + this.thick * 0.7;
      return { x: sx + this.px + Math.cos(a) * L, y: this.py + dy + Math.sin(a) * L, a };
    }
    draw(ctx, sx, dy, t) {
      const a = this.angle(t), r = this.recoil(t), heat = this.heat(t), hot = this.hot(t);
      ctx.save();
      ctx.translate(sx + this.px, this.py + dy);
      ctx.rotate(a);
      if (this.twin) {
        ctx.save(); ctx.translate(0, -this.thick * 0.55); P.barrel(ctx, this.len, this.thick * 0.8, r, { heat, hot }); ctx.restore();
        ctx.save(); ctx.translate(0, this.thick * 0.55); P.barrel(ctx, this.len * 0.96, this.thick * 0.8, r * 0.7, { heat, hot }); ctx.restore();
      } else {
        P.barrel(ctx, this.len, this.thick, r, { coils: this.coils, heat, hot });
      }
      // breech block / mantlet
      ctx.fillStyle = P.metal(ctx, -this.thick, this.thick, this.tone);
      U.roundRect(ctx, -this.thick * 1.1 - r * 0.3, -this.thick * 0.9, this.thick * 1.6, this.thick * 1.8, 5);
      ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.8)'; ctx.lineWidth = 1.5; ctx.stroke();
      ctx.restore();
      if (this.dome) P.turretDome(ctx, sx + this.px, this.py + dy + this.dome * 0.35, this.dome, this.tone);
      if (heat > 0.01) {
        const m = this.muzzle(sx, dy, t);
        P.glowSprite(ctx, WT.sprites.orange, m.x, m.y, 60 + 140 * heat, heat);
        P.glowSprite(ctx, WT.sprites.white, m.x, m.y, 30 + 40 * heat, heat * 0.9);
      }
    }
  }

  // ---------------------------------------------------------------- Car --
  class Car {
    constructor(kind, width, tone) {
      this.kind = kind;
      this.w = width;
      this.tone = tone || 0;
      this.left = 0;           // world x of the car's left edge (train front is world x = 0)
      this.guns = [];
      this.bogies = [80, width - 80];
      this.phase = U.hash(kind + width) % 100 / 16;
    }
    build() {
      const c = U.canvas(this.w + PAD * 2, SPR_H), x = c.getContext('2d');
      x.translate(PAD, -SPR_TOP);
      this.paintChassis(x);
      this.paint(x);
      P.weather(x, this.w, U.hash(this.kind + this.w), { holes: this.holes || 0 });
      this.sprite = c;
      return this;
    }
    paintChassis(x) {
      const w = this.w;
      x.fillStyle = '#121416';
      x.fillRect(4, 872, w - 8, 22);
      x.fillStyle = '#23272c';
      x.fillRect(4, 872, w - 8, 4);
      P.rivets(x, 14, 884, w - 28, 26, 2);
      P.hazard(x, 4, 886, 28, 8);
      P.hazard(x, w - 32, 886, 28, 8);
      // skirt shadow between bogies
      x.fillStyle = 'rgba(0,0,0,0.55)';
      x.fillRect(this.bogies[0] + 76, 894, Math.max(0, this.bogies[this.bogies.length - 1] - this.bogies[0] - 152), 10);
    }
    paint() {}

    // Suspension: soft body bob + jolts at the rail joints (joints are every 160px, fixed on screen).
    bob(sx, t) {
      const s = Math.sin(t * 7.3 + this.phase) * 1.4 + Math.sin(t * 13.1 + this.phase * 2) * 0.6;
      const j = ((sx + this.w * 0.5) % 160 + 160) % 160;
      const jolt = j < 18 ? Math.sin((j / 18) * Math.PI) * 2.2 : 0;
      return s - jolt;
    }

    draw(ctx, sx, st) {
      const dy = this.bob(sx, st.t);
      for (const b of this.bogies) P.bogie(ctx, sx + b, st.wheelAng, st.speed);
      if (st.speed > 420) {
        // cheap horizontal motion blur: a faint ghost trailing behind
        ctx.globalAlpha = U.clamp((st.speed - 420) / 900, 0, 0.3);
        ctx.drawImage(this.sprite, sx - PAD - st.speed * 0.014, SPR_TOP + dy);
        ctx.globalAlpha = 1;
      }
      ctx.drawImage(this.sprite, sx - PAD, SPR_TOP + dy);
      this.drawLive(ctx, sx, dy, st);
      return dy;
    }
    drawLive(ctx, sx, dy, st) { for (const g of this.guns) g.draw(ctx, sx, dy, st.t); }
  }

  // --------------------------------------------------------- Locomotive --
  class Locomotive extends Car {
    constructor() {
      super('loco', 680, 0);
      this.bogies = [90, 300, 560];
      this.turret = new Gun({ px: 340, py: 672, len: 170, thick: 26, twin: true, dome: 40, rest: -0.1, maxRecoil: 26 });
      this.mg = new Gun({ px: 590, py: 688, len: 70, thick: 9, dome: 14, rest: -0.18, maxRecoil: 6 });
      this.guns = [this.turret, this.mg];
      this.holes = 14;
    }
    paint(x) {
      const w = this.w;
      // cab
      x.beginPath();
      x.moveTo(26, 872); x.lineTo(26, 622); x.lineTo(50, 596); x.lineTo(232, 596); x.lineTo(254, 622); x.lineTo(254, 872); x.closePath();
      x.fillStyle = P.metal(x, 596, 872, 1); x.fill();
      x.strokeStyle = 'rgba(0,0,0,0.9)'; x.lineWidth = 2; x.stroke();
      x.fillStyle = '#0a0a0b'; x.fillRect(40, 586, 200, 12);
      P.rivets(x, 40, 610, 200, 20);
      // glowing slit windows
      for (let i = 0; i < 3; i++) {
        x.fillStyle = '#070707'; x.fillRect(56 + i * 60, 636, 46, 22);
        x.save(); x.shadowColor = ACCENT; x.shadowBlur = 16;
        x.fillStyle = '#ff8a2a'; x.fillRect(59 + i * 60, 644, 40, 7);
        x.restore();
      }
      P.plate(x, 40, 676, 98, 180, { tone: 1, spacing: 20 });
      P.plate(x, 144, 676, 98, 180, { tone: 1, spacing: 20 });
      P.stencil(x, 'WT-01', 141, 720, 30, '#d9d3c4');
      P.hazard(x, 60, 800, 160, 14);
      // engine hull
      x.beginPath();
      x.moveTo(254, 872); x.lineTo(254, 690); x.quadraticCurveTo(256, 676, 274, 676);
      x.lineTo(574, 676); x.lineTo(628, 698); x.lineTo(668, 770); x.lineTo(668, 872); x.closePath();
      x.fillStyle = P.metal(x, 676, 872, 0); x.fill();
      x.strokeStyle = 'rgba(0,0,0,0.9)'; x.lineWidth = 2; x.stroke();
      // armored hood band + vents
      x.fillStyle = '#16191c'; x.fillRect(262, 680, 312, 16);
      P.vents(x, 300, 684, 120, 8, 8);
      P.vents(x, 440, 684, 110, 8, 7);
      // side armor panels
      P.plate(x, 266, 712, 104, 146, { spacing: 24 });
      P.plate(x, 376, 712, 104, 146, { spacing: 24 });
      P.plate(x, 486, 712, 110, 146, { spacing: 24 });
      x.beginPath(); x.moveTo(602, 712); x.lineTo(626, 712); x.lineTo(658, 772); x.lineTo(658, 858); x.lineTo(602, 858); x.closePath();
      x.fillStyle = P.metal(x, 712, 858, 1); x.fill(); x.strokeStyle = '#000'; x.stroke();
      P.insignia(x, 428, 786, 50, ACCENT);
      // chains draped over the armor
      P.chain(x, 272, 708, 372, 708, 22);
      P.chain(x, 484, 708, 596, 708, 26);
      // smokestacks
      x.fillStyle = P.metal(x, 600, 680, 1);
      x.fillRect(496, 612, 34, 66); x.fillRect(420, 636, 22, 42);
      x.fillStyle = '#0b0c0d'; x.fillRect(490, 604, 46, 12); x.fillRect(416, 630, 30, 9);
      x.strokeStyle = 'rgba(0,0,0,0.9)'; x.strokeRect(496, 612, 34, 66);
      // headlight housing + nose details
      x.fillStyle = '#0b0c0d';
      x.beginPath(); x.arc(652, 742, 18, 0, 6.283); x.fill();
      x.fillStyle = '#ffd9a0';
      x.beginPath(); x.arc(652, 742, 10, 0, 6.283); x.fill();
      P.hazard(x, 610, 830, 54, 16);
      // plow
      x.beginPath(); x.moveTo(640, 872); x.lineTo(676, 872); x.lineTo(712, 936); x.lineTo(640, 936); x.closePath();
      x.fillStyle = P.metal(x, 872, 936, 1); x.fill(); x.strokeStyle = '#000'; x.stroke();
      for (let i = 0; i < 4; i++) { x.strokeStyle = 'rgba(255,122,26,0.5)'; x.beginPath(); x.moveTo(648 + i * 14, 878); x.lineTo(664 + i * 14, 932); x.stroke(); }
      // neon underglow strip
      P.neon(x, 30, 862, w - 22, 862, 3, ACCENT);
    }
    drawLive(ctx, sx, dy, st) {
      const t = st.t;
      P.flag(ctx, sx + 46, 500 + dy, 98, 84, 50, t, HOT);
      super.drawLive(ctx, sx, dy, st);
      // rotating amber beacon on the cab roof
      const b = 0.5 + 0.5 * Math.sin(t * 10);
      P.glowSprite(ctx, WT.sprites.orange, sx + 140, 582 + dy, 50 + 50 * b, 0.5 + 0.5 * b);
      // headlight core
      P.glowSprite(ctx, WT.sprites.white, sx + 652, 742 + dy, 70, 0.9);
      P.glowSprite(ctx, WT.sprites.orange, sx + 652, 742 + dy, 160, 0.6);
      // window flicker
      P.glowSprite(ctx, WT.sprites.orange, sx + 140, 648 + dy, 260, 0.18 + 0.06 * Math.sin(t * 23));
    }
    stack(sx, dy) { return { x: sx + 513, y: 604 + dy }; }
    headlight(sx, dy) { return { x: sx + 652, y: 742 + dy }; }
  }

  // --------------------------------------------------- GifterCannonWagon --
  // Accepts { username, avatarUrl, giftCount, tier, eventId }. One wagon per gifter.
  class GifterCannonWagon extends Car {
    constructor(g) {
      super('gifter', 600, 0);
      this.g = Object.assign({ username: 'Anonymous', avatarUrl: '', giftCount: 1, tier: '1000', eventId: '' }, g);
      this.g.username = U.cleanName(this.g.username);
      this.cannon = new Gun({ px: 330, py: 742, len: 280, thick: 32, coils: 3, dome: 66, rest: -0.12, maxRecoil: 40 });
      this.guns = [this.cannon];
      this.holes = 6;
      this.Tc = 0;
      this.shotTimes = [];
      this.avatar = null;
      this.hue = U.hash(this.g.username) % 360;
      if (this.g.avatarUrl) this.loadAvatar(this.g.avatarUrl);
    }
    loadAvatar(url) {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => { this.avatar = img; };
      img.onerror = () => {
        // retry without CORS so the avatar still shows (canvas export may be tainted then)
        if (img.crossOrigin) { const i2 = new Image(); i2.onload = () => { this.avatar = i2; }; i2.src = url; }
      };
      img.src = url;
    }
    rank() {
      const n = this.g.giftCount;
      if (n >= 50) return { label: 'GENERAL', icon: 'crown' };
      if (n >= 20) return { label: 'COLONEL', icon: 'star' };
      if (n >= 10) return { label: 'SERGEANT', n: 3 };
      if (n >= 5) return { label: 'CORPORAL', n: 2 };
      return { label: 'PRIVATE', n: 1 };
    }
    tierLabel() {
      const t = String(this.g.tier);
      return t === '3000' ? 'TIER 3' : t === '2000' ? 'TIER 2' : t.toLowerCase() === 'prime' ? 'PRIME' : 'TIER 1';
    }
    // Schedule this wagon's cannon routine around Tc (the moment it's centred on screen).
    schedule(Tc) {
      this.Tc = Tc;
      const c = this.cannon;
      c.aimTo(Tc - 1.0, Tc - 0.3, -0.52);
      c.chargeFrom = Tc - 0.55; c.chargeTo = Tc + 0.15;
      this.shotTimes = [Tc + 0.15];
      if (this.g.giftCount >= 5) this.shotTimes.push(Tc + 0.8);
      if (this.g.giftCount >= 20) this.shotTimes.push(Tc + 1.25);
      c.aimTo(Tc + 1.5, Tc + 2.1, -0.16);
    }
    paint(x) {
      const w = this.w;
      // armored side skirt
      P.plate(x, 8, 790, w - 16, 82, { c: 10, spacing: 26 });
      P.hazard(x, 14, 782, w - 28, 10);
      // gunner cupola + shield wall
      P.plate(x, 14, 690, 34, 92, { c: 4, rivets: false, tone: 1 });
      P.sandbags(x, 52, 790, 150);
      // SUB GIFTER neon label box
      x.fillStyle = '#0a0a0b';
      U.chamfer(x, 24, 806, 136, 48, 8); x.fill();
      x.strokeStyle = ACCENT; x.lineWidth = 2; x.save(); x.shadowColor = ACCENT; x.shadowBlur = 14; x.stroke(); x.restore();
      P.glowText(x, WT.cfg.labels.gifter, 92, 824, 19, ACCENT, { core: '#ffd2a8', blur: 16 });
      P.glowText(x, '★ ★ ★', 92, 843, 12, GOLD, { blur: 6 });
      // gift-count badge housing
      x.fillStyle = '#0a0a0b';
      U.chamfer(x, 480, 802, 104, 56, 8); x.fill();
      x.strokeStyle = GOLD; x.lineWidth = 2; x.stroke();
      // ammo crates and shells on deck
      P.crate(x, 470, 740, 62, 46, 'AMMO');
      P.crate(x, 536, 752, 50, 34, '', 'olive');
      P.shells(x, 540, 750, 4);
      // turret ring
      x.fillStyle = '#16191c'; U.roundRect(x, 246, 776, 170, 16, 6); x.fill();
      P.neon(x, 20, 866, w - 20, 866, 2, ACCENT);
    }
    drawAvatar(ctx, cx, cy, r, t) {
      // shield-shaped frame
      const shield = () => {
        ctx.beginPath();
        ctx.moveTo(cx - r, cy - r * 0.95);
        ctx.lineTo(cx + r, cy - r * 0.95);
        ctx.lineTo(cx + r, cy + r * 0.2);
        ctx.quadraticCurveTo(cx + r, cy + r * 0.85, cx, cy + r * 1.25);
        ctx.quadraticCurveTo(cx - r, cy + r * 0.85, cx - r, cy + r * 0.2);
        ctx.closePath();
      };
      ctx.save();
      shield();
      ctx.fillStyle = `hsl(${this.hue},35%,18%)`;
      ctx.fill();
      ctx.clip();
      if (this.avatar) {
        ctx.drawImage(this.avatar, cx - r, cy - r, r * 2, r * 2.3);
      } else {
        // placeholder: helmeted soldier silhouette + initials
        ctx.fillStyle = `hsl(${this.hue},30%,30%)`;
        ctx.beginPath(); ctx.arc(cx, cy - r * 0.1, r * 0.42, Math.PI, 0); ctx.lineTo(cx + r * 0.52, cy); ctx.lineTo(cx - r * 0.52, cy); ctx.fill();
        ctx.fillStyle = '#1a1c1f';
        ctx.beginPath(); ctx.ellipse(cx, cy + r * 0.85, r * 0.75, r * 0.5, 0, Math.PI, 0); ctx.fill();
        ctx.fillStyle = '#e9e4da';
        ctx.font = `${r * 0.55}px ${P.FONT_STENCIL}`;
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(this.g.username.replace(/[^a-z0-9]/gi, '').slice(0, 2).toUpperCase() || '?', cx, cy + r * 0.45);
      }
      ctx.restore();
      shield();
      ctx.lineWidth = 4;
      ctx.strokeStyle = GOLD;
      ctx.save(); ctx.shadowColor = ACCENT; ctx.shadowBlur = 14 + 6 * Math.sin(t * 6); ctx.stroke(); ctx.restore();
    }
    drawLive(ctx, sx, dy, st) {
      const t = st.t, Tc = this.Tc;
      // gunner avatar on the deck, behind the cannon
      const pop = U.easeOutBack(U.inv(Tc - 1.6, Tc - 1.2, t));
      if (pop > 0.01) {
        ctx.save();
        ctx.translate(sx + 128, 742 + dy);
        ctx.scale(pop, pop);
        this.drawAvatar(ctx, 0, -18, 44, t);
        // crown drops onto the shield
        const cd = U.easeOutBack(U.inv(Tc - 1.25, Tc - 0.9, t));
        ctx.globalAlpha = U.clamp(cd * 2, 0, 1);
        P.glowSprite(ctx, WT.sprites.gold, 0, -84 - (1 - cd) * 60, 90, 0.5 * cd);
        P.crown(ctx, 0, -84 - (1 - cd) * 60 + Math.sin(t * 4) * 2, 34, GOLD);
        ctx.globalAlpha = 1;
        ctx.restore();
      }
      super.drawLive(ctx, sx, dy, st);
      this.drawPlate(ctx, sx, dy, t);
      this.drawCounter(ctx, sx, dy, t);
      // floating "+N SUBS" callout after the first shot
      const f = t - this.shotTimes[0];
      if (f > 0 && f < 1.8) {
        const a = f < 0.2 ? f / 0.2 : 1 - U.inv(1.2, 1.8, f);
        ctx.globalAlpha = a;
        P.glowText(ctx, `+${this.g.giftCount} SUB${this.g.giftCount > 1 ? 'S' : ''}`, sx + 250, 560 + dy - f * 70, 50, GOLD, { glowColor: ACCENT, core: '#fff3d0' });
        ctx.globalAlpha = 1;
      }
    }
    drawPlate(ctx, sx, dy, t) {
      const Tc = this.Tc, k = U.inv(Tc - 1.7, Tc - 1.3, t);
      const x = sx + 172, y = 798 + dy, w = 298, h = 66;
      // dark empty slot until the plate slams in
      ctx.fillStyle = '#08090a';
      U.chamfer(ctx, x, y, w, h, 10); ctx.fill();
      if (k <= 0) return;
      const s = U.easeOutBack(k);
      ctx.save();
      ctx.translate(x + w / 2, y + h / 2);
      ctx.scale(s, s);
      ctx.translate(-w / 2, -h / 2);
      const g = ctx.createLinearGradient(0, 0, 0, h);
      g.addColorStop(0, '#2a2e33'); g.addColorStop(1, '#0d0f11');
      ctx.fillStyle = g;
      U.chamfer(ctx, 0, 0, w, h, 10); ctx.fill();
      ctx.lineWidth = 2.5; ctx.strokeStyle = ACCENT;
      ctx.save(); ctx.shadowColor = ACCENT; ctx.shadowBlur = 12; ctx.stroke(); ctx.restore();
      // rank icon
      const rk = this.rank();
      if (rk.icon === 'crown') P.crown(ctx, 30, h / 2, 30, GOLD);
      else if (rk.icon === 'star') P.star(ctx, 30, h / 2, 16, GOLD);
      else P.chevrons(ctx, 30, h / 2 + 4, 26, rk.n, GOLD);
      // username — always fits, never overlaps
      ctx.fillStyle = '#f4efe6';
      ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
      U.fitFont(ctx, this.g.username, w - 70, 34, P.FONT_UI, '700', 16);
      ctx.fillText(this.g.username, 56, 38);
      ctx.font = `500 14px ${P.FONT_UI}`;
      ctx.fillStyle = '#ffb070';
      ctx.fillText(`${rk.label}  •  ${this.tierLabel()}  •  ${this.g.giftCount} GIFTED`, 56, 57);
      ctx.restore();
      // impact flash when it lands
      if (k < 1) P.glowSprite(ctx, WT.sprites.orange, x + w / 2, y + h / 2, 420, (1 - k) * 0.6);
    }
    drawCounter(ctx, sx, dy, t) {
      const f = U.inv(this.shotTimes[0], this.shotTimes[0] + 0.9, t);
      const n = Math.round(this.g.giftCount * U.easeOutCubic(f));
      const x = sx + 532, y = 822 + dy;
      P.glowText(ctx, `×${n}`, x, y, n >= 100 ? 26 : 34, GOLD, { blur: f > 0 && f < 1 ? 24 : 10, core: '#fff1c8' });
      ctx.font = `600 12px ${P.FONT_UI}`; ctx.textAlign = 'center'; ctx.fillStyle = '#c9b48a';
      ctx.fillText('GIFTED SUBS', x, 849 + dy);
    }
  }

  // ------------------------------------------------------- ThemedWagon --
  class ThemedWagon extends Car {
    constructor(theme, data) {
      super(theme, 560, theme === 'blackops' ? 2 : theme === 'warzone' ? 3 : 0);
      this.data = data || {};
      if (theme === 'hype') {
        this.guns = [
          new Gun({ px: 150, py: 676, len: 80, thick: 10, dome: 16, rest: -0.35, maxRecoil: 6, twin: true }),
          new Gun({ px: 410, py: 676, len: 80, thick: 10, dome: 16, rest: -0.42, maxRecoil: 6, twin: true }),
        ];
      } else if (theme === 'warzone') {
        this.guns = [new Gun({ px: 430, py: 728, len: 170, thick: 22, dome: 40, rest: -0.3, maxRecoil: 20, tone: 3 })];
        this.fires = [[150, 714, 1.1]];
      } else {
        this.guns = [new Gun({ px: 470, py: 684, len: 90, thick: 12, dome: 18, rest: -0.25, maxRecoil: 8, tone: 2 })];
        this.fires = [[300, 690, 0.7]];
      }
      this.holes = theme === 'hype' ? 8 : 18;
    }
    paint(x) {
      const w = this.w, th = this.kind, L = WT.cfg.labels;
      if (th === 'hype') {
        P.plate(x, 10, 680, w - 20, 192, { c: 12, spacing: 24 });
        for (let i = 1; i < 6; i++) { x.fillStyle = 'rgba(0,0,0,0.35)'; x.fillRect(10 + i * ((w - 20) / 6), 690, 3, 172); }
        x.fillStyle = '#070708'; U.chamfer(x, 50, 706, w - 100, 92, 12); x.fill();
        x.strokeStyle = '#3a2a1c'; x.lineWidth = 3; x.stroke();
        P.hazard(x, 10, 672, w - 20, 10);
      } else if (th === 'blackops') {
        P.plate(x, 10, 690, w - 20, 182, { c: 6, tone: 2, spacing: 30 });
        x.save(); x.beginPath(); x.rect(10, 690, w - 20, 182); x.clip();
        x.strokeStyle = 'rgba(255,255,255,0.035)'; x.lineWidth = 26;
        for (let i = -200; i < w + 200; i += 70) { x.beginPath(); x.moveTo(i, 872); x.lineTo(i + 180, 690); x.stroke(); }
        x.restore();
        P.stencil(x, L.blackops, w / 2 - 30, 742, 52, '#d8d2c6', 'center', 380);
        P.neon(x, 60, 774, w - 120, 774, 3, ACCENT);
        P.skull(x, w - 62, 740, 54, '#d8d2c6');
        // rocket pod on the roof
        x.fillStyle = P.metal(x, 650, 690, 2); U.chamfer(x, 90, 652, 170, 38, 6); x.fill();
        x.strokeStyle = '#000'; x.stroke();
        for (let r = 0; r < 2; r++) for (let c = 0; c < 6; c++) {
          x.fillStyle = '#050505'; x.beginPath(); x.arc(108 + c * 27, 663 + r * 16, 6, 0, 6.283); x.fill();
          x.fillStyle = HOT; x.beginPath(); x.arc(108 + c * 27, 663 + r * 16, 2.3, 0, 6.283); x.fill();
        }
      } else {
        // warzone: open gondola with sandbags and containers
        P.plate(x, 10, 760, w - 20, 112, { c: 8, tone: 3, spacing: 26 });
        P.crate(x, 40, 712, 84, 48, 'AMMO', 'olive');
        P.crate(x, 128, 724, 64, 36, '', 'olive');
        P.shells(x, 200, 758, 5);
        P.sandbags(x, 262, 762, 120);
        x.fillStyle = '#0a0a0b'; U.chamfer(x, 40, 666, 250, 40, 6); x.fill();
        x.strokeStyle = ACCENT; x.lineWidth = 2; x.stroke();
        P.glowText(x, L.warzone, 165, 687, 30, ACCENT, { core: '#ffd8b0', blur: 14 });
        x.fillStyle = '#16191c'; x.fillRect(88, 706, 6, 8); x.fillRect(236, 706, 6, 8);
      }
      P.neon(x, 20, 866, w - 20, 866, 2, th === 'blackops' ? HOT : ACCENT);
    }
    drawLive(ctx, sx, dy, st) {
      const t = st.t;
      if (this.kind === 'hype') this.drawHype(ctx, sx, dy, t);
      super.drawLive(ctx, sx, dy, st);
      if (this.kind === 'warzone') P.flag(ctx, sx + 520, 640 + dy, 120, 70, 42, t + 1, ACCENT);
      if (this.kind !== 'hype') this.drawRecruits(ctx, sx, dy);
    }
    drawHype(ctx, sx, dy, t) {
      const L = WT.cfg.labels, hype = this.data.hype || {};
      const flick = 0.85 + 0.15 * Math.sin(t * 31) * Math.sin(t * 7);
      ctx.globalAlpha = flick;
      P.glowText(ctx, L.hype, sx + this.w / 2, 744 + dy, 56, ACCENT, { core: '#ffd9b8', blur: 26 });
      ctx.globalAlpha = 1;
      // level + progress bar
      const lvl = hype.level || 1, prog = hype.goal ? U.clamp(hype.progress / hype.goal, 0, 1) : 0;
      const bx = sx + 60, by = 812 + dy, bw = this.w - 120;
      ctx.fillStyle = '#08090a'; U.chamfer(ctx, bx, by, bw, 36, 6); ctx.fill();
      ctx.strokeStyle = '#3d2b1c'; ctx.lineWidth = 2; ctx.stroke();
      const fill = (bw - 120) * prog * U.easeOutCubic(U.clamp((t - (this.data.t0 || 0)) / 1.2, 0, 1));
      const g = ctx.createLinearGradient(bx + 110, 0, bx + 110 + fill, 0);
      g.addColorStop(0, HOT); g.addColorStop(1, '#ffb347');
      ctx.fillStyle = g;
      ctx.fillRect(bx + 110, by + 9, fill, 18);
      P.glowSprite(ctx, WT.sprites.orange, bx + 110 + fill, by + 18, 60, 0.8);
      ctx.font = `700 20px ${P.FONT_UI}`; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'; ctx.fillStyle = GOLD;
      ctx.fillText(hype.complete ? 'COMPLETE' : `LEVEL ${lvl}`, bx + 12, by + 19);
    }
    drawRecruits(ctx, sx, dy) {
      const list = this.data.recruits || [];
      const y = this.kind === 'blackops' ? 798 : 790;
      const slotW = 236;
      list.slice(0, 2).forEach((r, i) => {
        const x = sx + 30 + i * (slotW + 14) + (this.kind === 'warzone' ? 0 : 0);
        ctx.fillStyle = 'rgba(8,9,10,0.92)';
        U.chamfer(ctx, x, y + dy, slotW, 54, 7); ctx.fill();
        ctx.strokeStyle = r.type === 'resub' ? GOLD : ACCENT; ctx.lineWidth = 2; ctx.stroke();
        ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = '#f4efe6';
        U.fitFont(ctx, U.cleanName(r.username), slotW - 24, 24, P.FONT_UI, '700', 13);
        ctx.fillText(U.cleanName(r.username), x + 12, y + dy + 27);
        ctx.font = `500 13px ${P.FONT_UI}`; ctx.fillStyle = r.type === 'resub' ? GOLD : '#ffb070';
        ctx.fillText(r.type === 'resub' ? `VETERAN • ${r.months || 1} MONTHS` : 'NEW RECRUIT', x + 12, y + dy + 45);
      });
    }
  }

  // ------------------------------------------------- Heavy artillery --
  class ArtilleryWagon extends Car {
    constructor() {
      super('artillery', 820, 0);
      this.bogies = [90, 410, 730];
      this.guns = [
        new Gun({ px: 170, py: 752, len: 210, thick: 24, dome: 44, rest: -0.28, maxRecoil: 26, coils: 2 }),
        new Gun({ px: 410, py: 726, len: 320, thick: 40, dome: 84, rest: -0.2, maxRecoil: 46, coils: 3 }),
        new Gun({ px: 650, py: 752, len: 210, thick: 24, dome: 44, rest: -0.36, maxRecoil: 26, coils: 2 }),
      ];
      this.holes = 10;
    }
    paint(x) {
      const w = this.w;
      P.plate(x, 8, 784, w - 16, 88, { c: 12, spacing: 28 });
      P.hazard(x, 14, 776, w - 28, 10);
      // outrigger legs
      for (const lx of [40, w - 70]) {
        x.fillStyle = '#16191c';
        x.beginPath(); x.moveTo(lx, 860); x.lineTo(lx + 30, 860); x.lineTo(lx + 44, 930); x.lineTo(lx - 14, 930); x.closePath(); x.fill();
        x.strokeStyle = '#3a3f46'; x.stroke();
      }
      // energy cores
      for (const cx of [292, 528]) {
        x.fillStyle = '#0a0a0b'; U.roundRect(x, cx - 18, 796, 36, 64, 8); x.fill();
        x.save(); x.shadowColor = ACCENT; x.shadowBlur = 20;
        const g = x.createLinearGradient(0, 802, 0, 854); g.addColorStop(0, '#ffd08a'); g.addColorStop(1, HOT);
        x.fillStyle = g; U.roundRect(x, cx - 11, 802, 22, 52, 6); x.fill();
        x.restore();
      }
      x.fillStyle = '#0a0a0b'; U.chamfer(x, 340, 798, 140, 60, 8); x.fill();
      x.strokeStyle = GOLD; x.lineWidth = 2; x.stroke();
      P.crown(x, 410, 818, 30, GOLD);
      P.stencil(x, 'ULTIMATE', 410, 845, 15, GOLD);
      P.stencil(x, 'HEAVY ARTILLERY', 150, 826, 22, '#cfc8b8', 'center', 230);
      P.stencil(x, 'GIFTER DIVISION', 676, 826, 22, '#cfc8b8', 'center', 230);
      P.neon(x, 20, 866, w - 20, 866, 3, GOLD);
    }
    drawLive(ctx, sx, dy, st) {
      super.drawLive(ctx, sx, dy, st);
      const p = 0.6 + 0.4 * Math.sin(st.t * 8);
      P.glowSprite(ctx, WT.sprites.orange, sx + 292, 828 + dy, 110, p * 0.7);
      P.glowSprite(ctx, WT.sprites.orange, sx + 528, 828 + dy, 110, p * 0.7);
    }
  }

  // ----------------------------------------------------------- Caboose --
  class Caboose extends Car {
    constructor() {
      super('caboose', 420, 1);
      this.guns = [new Gun({ px: 70, py: 690, len: 80, thick: 10, dome: 16, rest: -0.2, maxRecoil: 6, flip: true, tone: 1 })];
      this.holes = 22;
      this.fires = [[320, 702, 0.9]];
    }
    paint(x) {
      const w = this.w;
      P.plate(x, 10, 700, w - 20, 172, { c: 10, tone: 1, spacing: 24 });
      P.plate(x, 150, 648, 130, 56, { c: 6, tone: 1, spacing: 20 });
      for (let i = 0; i < 3; i++) {
        x.fillStyle = '#060606'; x.fillRect(166 + i * 36, 664, 26, 18);
        x.save(); x.shadowColor = ACCENT; x.shadowBlur = 10; x.fillStyle = '#ff9a3a'; x.fillRect(169 + i * 36, 670, 20, 6); x.restore();
      }
      P.stencil(x, 'REAR GUARD', w / 2 + 10, 760, 30, '#d9d3c4', 'center', 300);
      P.hazard(x, 40, 790, w - 80, 14);
      P.chain(x, 40, 820, w - 40, 820, 18);
      P.skull(x, w / 2 + 10, 838, 30, '#8f8a80');
      x.fillStyle = '#08090a'; x.fillRect(10, 740, 10, 110);
      P.neon(x, 20, 866, w - 20, 866, 2, HOT);
    }
    drawLive(ctx, sx, dy, st) {
      super.drawLive(ctx, sx, dy, st);
      P.flag(ctx, sx + 392, 600 + dy, 104, 70, 42, st.t + 2, HOT);
      // red tail lights at the rear (left) end
      const fade = st.tailFade == null ? 1 : st.tailFade;
      const blink = 0.75 + 0.25 * Math.sin(st.t * 6);
      for (const ly of [762, 832]) {
        ctx.fillStyle = '#2a0805'; ctx.beginPath(); ctx.arc(sx + 12, ly + dy, 9, 0, 6.283); ctx.fill();
        P.glowSprite(ctx, WT.sprites.red, sx + 12, ly + dy, 70, blink * fade);
        P.glowSprite(ctx, WT.sprites.red, sx + 4, ly + dy, 220, 0.45 * blink * fade);
      }
    }
  }

  WT.Gun = Gun;
  WT.Car = Car;
  WT.Locomotive = Locomotive;
  WT.GifterCannonWagon = GifterCannonWagon;
  WT.ThemedWagon = ThemedWagon;
  WT.ArtilleryWagon = ArtilleryWagon;
  WT.Caboose = Caboose;
})(window.WT);

/* ---- js/show/run.js ---- */
/* War Train — one 15-second train pass (six scenes). A Run owns the train composition, the motion
   curve, every timed cue (cannon fire, steam, sound) and the HUD text. Scene timing:
     1  0–2s    approach out of the smoke          4   7–10s  HYPE TRAIN / BLACK OPS / WARZONE pass
     2  2–4s    armored locomotive + turret fire   5  10–13s  heavy artillery + THANK YOU celebration
     3  4–7s    SUB GIFTER cannon wagon(s)         6  13–15s  caboose exits, tail lights fade
   Every extra gifter wagon in the same pass stretches scene 3 by cfg.extraGifterSeconds (G). */
window.WT = window.WT || {};
(function (WT) {
  'use strict';
  const U = WT.U, P = WT.P;
  const C = 960, GAP = 26;
  const ACCENT = '#ff7a1a', GOLD = '#ffc840';

  class Run {
    constructor(ctrl, payload) {
      const cfg = WT.cfg;
      this.ctrl = ctrl;
      this.fx = ctrl.fx;
      this.sound = ctrl.sound;
      this.p = payload;
      // scene 3 timing: one slot per gifter, stretched for big SUB BOMB killstreaks
      this.strikes = new WT.StrikeManager(this.fx, this.sound);
      const slots = [];
      let Tc = 5.5;
      payload.gifters.forEach((g, i) => {
        const ex = WT.killstreakFor(g.giftCount).extra || 0;
        slots.push({ Tc, ex });
        Tc += cfg.extraGifterSeconds + ex;
      });
      const last = slots[slots.length - 1];
      const G = (this.G = last ? last.Tc - 5.5 + last.ex : 0);
      this.D = cfg.showDuration + G;

      // --- composition (front → rear) -------------------------------------
      this.loco = new WT.Locomotive();
      this.gifterCars = payload.gifters.map((g) => new WT.GifterCannonWagon(g));
      this.hype = new WT.ThemedWagon('hype', { hype: payload.hype, t0: 7 + G - 0.8 });
      this.blackops = new WT.ThemedWagon('blackops', { recruits: payload.recruits.slice(0, 2) });
      this.warzone = new WT.ThemedWagon('warzone', { recruits: payload.recruits.slice(2, 4) });
      this.art = new WT.ArtilleryWagon();
      this.caboose = new WT.Caboose();
      this.cars = [this.loco, ...this.gifterCars, this.hype, this.blackops, this.warzone, this.art, this.caboose];
      let x = 0;
      for (const car of this.cars) {
        car.left = x - car.w;
        x = car.left - GAP;
        car.build();
      }

      // --- motion curve: screen x of the train front over time ------------
      const ctr = (car, shift) => C + (shift || 0) - (car.left + car.w / 2);
      const K = [[0, -760], [1.2, 150], [3.0, ctr(this.loco)]];
      this.gifterCars.forEach((car, i) => {
        const sl = slots[i];
        K.push([sl.Tc - 0.9, ctr(car, -75)], [sl.Tc + 0.9 + sl.ex, ctr(car, 75)]);
        car.schedule(sl.Tc);
      });
      K.push([8.3 + G, ctr(this.blackops)]);
      K.push([10.6 + G, ctr(this.art, -60)], [12.4 + G, ctr(this.art, 60)]);
      const exitOff = 1990 - this.caboose.left;
      K.push([14.6 + G, exitOff], [15 + G, exitOff + 520]);
      this.off = U.monotone(K.map((k) => k[0]), K.map((k) => k[1]));

      this.cues = [];
      this.buildCues();
      this.cues.sort((a, b) => a.t - b.t);
      this.ci = 0;
      this.prevT = -1;
      this.acc = {};
    }

    vel(t) { return (this.off(t + 0.01) - this.off(t - 0.01)) / 0.02; }
    sxOf(car, t) { return car.left + this.off(t); }
    at(t, fn) { this.cues.push({ t, fn }); }

    fire(car, gun, t, o) {
      o = o || {};
      const sx = this.sxOf(car, t), dy = car.bob(sx, t);
      gun.lastFire = t;
      const m = gun.muzzle(sx, dy, t);
      if (o.tracer) {
        this.fx.tracer(m.x, m.y, m.a + this.fx.r(-0.05, 0.05), { len: 110 });
        this.fx.flash(m.x, m.y, 50, m.a, { life: 0.05 });
        return m;
      }
      this.fx.muzzle(m.x, m.y, m.a, o.scale || 1);
      if (o.target) this.fx.blast(m.x, m.y, m.a, { target: o.target, life: o.life || 0.55, gold: o.gold, scale: o.burst || 1, size: o.size || 24 });
      this.fx.shake(o.shake || 6, 0.25);
      this.sound.play('cannon', { gain: o.gain || 1 });
      return m;
    }

    buildCues() {
      const G = this.G, fx = this.fx, D = this.D;
      // Scene 1 — approach
      this.at(0.05, () => this.sound.play('rumble', { duration: D - 0.3 }));
      this.at(0.7, () => this.sound.play('whistle'));
      // Scene 2 — locomotive
      const tur = this.loco.turret, mg = this.loco.mg;
      tur.aimTo(1.9, 2.4, -0.34);
      tur.aimTo(3.7, 4.3, -0.1);
      mg.aimTo(2.0, 2.2, -0.3);
      this.at(2.0, () => this.sound.play('clank'));
      this.at(2.55, () => this.fire(this.loco, tur, 2.55, { target: [1500, 300], shake: 8 }));
      this.at(3.3, () => this.fire(this.loco, tur, 3.3, { target: [1680, 360], shake: 8 }));
      this.at(3.0, () => {
        const sx = this.sxOf(this.loco, 3), dy = this.loco.bob(sx, 3);
        fx.steam(sx + 300, 682 + dy, { n: 8 });
        fx.steam(sx + 460, 682 + dy, { n: 8 });
        for (const b of [90, 300, 560]) fx.steam(sx + b, 905, { n: 4, vx: -160, vy: -30, size: 40 });
        this.sound.play('steam');
      });
      for (let tt = 2.25; tt < 3.85; tt += 0.075) {
        if ((tt > 2.7 && tt < 2.95)) continue; // short pause between bursts
        this.at(tt, ((T) => () => { this.fire(this.loco, mg, T, { tracer: true }); })(tt));
      }
      // Scene 3 — gifter cannon wagons
      this.gifterCars.forEach((car) => {
        const g = car.g;
        this.at(car.Tc - 1.65, () => this.sound.play('clank'));
        this.at(car.Tc - 0.55, () => this.sound.play('reload'));
        car.shotTimes.forEach((st, k) => {
          this.at(st, () => {
            const m = this.fire(car, car.cannon, st, {
              target: null, scale: k === 0 ? 1.5 : 1.1, shake: k === 0 ? 14 : 8, gain: 1.3,
            });
            fx.blast(m.x, m.y, m.a, { target: [m.x + 470 + k * 60, m.y - 300 - k * 40], life: 0.55, gold: g.giftCount >= 10 || k === 0, scale: k === 0 ? 1.4 : 1, size: k === 0 ? 30 : 22 });
            if (k === 0) {
              this.strikes.start(g, st + 0.05);
              this.ctrl.onGifterFired(g);
              this.sound.play('sting', { gain: 0.8 });
            }
          });
        });
        this.at(car.Tc + 1.6, () => this.sound.play('reload'));
      });
      // Scene 4 — themed wagons
      for (let tt = 7.0 + G; tt < 8.5 + G; tt += 0.09) {
        this.at(tt, ((T) => () => { this.hype.guns.forEach((gn) => this.fire(this.hype, gn, T, { tracer: true })); })(tt));
      }
      this.at(8.4 + G, () => this.fire(this.blackops, this.blackops.guns[0], 8.4 + G, { tracer: true }));
      this.warzone.guns[0].aimTo(8.6 + G, 9.1 + G, -0.55);
      this.at(9.45 + G, () => this.fire(this.warzone, this.warzone.guns[0], 9.45 + G, { target: [1450, 280], shake: 9 }));
      // Scene 5 — heavy artillery volleys
      const Ta = 11.5 + G, ag = this.art.guns;
      ag[0].aimTo(9.9 + G, 10.5 + G, -0.72);
      ag[1].aimTo(9.9 + G, 10.5 + G, -0.98);
      ag[2].aimTo(9.9 + G, 10.5 + G, -0.62);
      const targets = [[[560, 250], [960, 150], [1360, 250]], [[700, 330], [1080, 200], [1500, 300]], [[460, 320], [860, 210], [1240, 160]]];
      [Ta - 0.9, Ta - 0.1, Ta + 0.7].forEach((tv, v) => {
        if (v === 0) this.at(tv, () => this.sound.play('sting', { gain: 1.2 }));
        ag.forEach((gn, i) => {
          const T = tv + i * 0.05;
          this.at(T, () => this.fire(this.art, gn, T, { target: targets[v][i], gold: true, burst: i === 1 ? 1.5 : 1.15, scale: i === 1 ? 1.6 : 1.1, shake: 16, life: 0.5, size: i === 1 ? 32 : 24 }));
        });
      });
      ag.forEach((gn, i) => gn.aimTo(Ta + 1.3, Ta + 2.0, gn.rest));
      // Scene 6 — departure
      this.at(13.1 + G, () => this.sound.play('whistle', { gain: 0.6 }));
      this.at(13.3 + G, () => {
        const sx = this.sxOf(this.caboose, 13.3 + G);
        fx.steam(sx + 30, 880, { n: 5, vx: -220, vy: -30, size: 36, alpha: 0.35 });
        this.sound.play('steam');
      });
      this.caboose.guns[0].aimTo(12.6 + G, 13.0 + G, -0.4);
    }

    // emit `rate` particles per second deterministically
    every(key, rate, dt, fn) {
      this.acc[key] = (this.acc[key] || 0) + rate * dt;
      while (this.acc[key] >= 1) { this.acc[key] -= 1; fn(); }
    }

    update(t, dt) {
      while (this.ci < this.cues.length && this.cues[this.ci].t <= t) {
        if (this.cues[this.ci].t > this.prevT) this.cues[this.ci].fn();
        this.ci++;
      }
      this.prevT = t;
      this.strikes.update(t, dt);
      const fx = this.fx, D = this.D, off = this.off(t), v = this.vel(t);
      // ambient battlefield: distant impacts, flak and burning damage on the wagons
      const war = WT.cfg.warIntensity * U.envelope(t, 0.3, D - 1.8, 0.8, 1.2);
      if (war > 0) {
        this.every('farboom', 0.75 * war, dt, () => fx.groundBlast(fx.r(80, 1840), 930, fx.r(0.3, 0.5), { layer: 'back', shake: false }));
        const flakOn = Math.sin(t * 1.7) > 0.2;
        if (flakOn) {
          if (!this.flakX || fx.rnd() < 0.01) this.flakX = fx.r(150, 1770);
          this.every('flak', 14 * war, dt, () => fx.tracer(this.flakX + fx.r(-8, 8), 930, -1.25 + Math.sin(t * 2.3) * 0.25, { layer: 'back', speed: 1500, len: 70, life: 0.55, color: '255,110,50' }));
        }
        this.every('puff', 1.6 * war, dt, () => {
          const x = fx.r(200, 1720), y = fx.r(250, 470);
          fx.flash(x, y, 120, 0, { layer: 'back', life: 0.08, color: 'white', alpha: 0.6 });
          fx.smoke(x, y, { n: 3, kind: 'soot', size: 34, spread: 10, vy: -10, jitter: 25, life: 2.2, alpha: 0.75, layer: 'back' });
          fx.sparks(x, y, { n: 6, speed: 300, gravity: 300, life: 0.6 });
        });
      }
      for (const car of this.cars) {
        if (!car.fires) continue;
        const sx = car.left + off;
        if (sx > 2000 || sx + car.w < -100) continue;
        const dy = car.bob(sx, t);
        car.fires.forEach((f, i) => {
          this.every(`fire${car.kind}${i}`, 22 * f[2], dt, () => fx.fire(sx + f[0], f[1] + dy, { n: 1, size: 20 * f[2], vx: -60, vy: -60, life: 0.7, spread: 10 * f[2] }));
          this.every(`soot${car.kind}${i}`, 6 * f[2], dt, () => fx.smoke(sx + f[0], f[1] + dy - 20, { n: 1, kind: 'soot', size: 30 * f[2], vx: -80, vy: -70, life: 2, alpha: 0.7, layer: 'front' }));
        });
      }
      const acc = (this.vel(t + 0.05) - this.vel(t - 0.05)) / 0.1;

      // battlefield smoke banks — heavy at the start, thin later, none near the end so the loop is clean
      const bankRate = t < 2.4 ? 14 : t < D - 4.6 ? 2.2 : 0;
      this.every('bank', bankRate * fx.mult, dt, () => fx.smoke(fx.r(-100, 2000), fx.r(830, 950), { n: 1, size: fx.r(130, 230), life: 3.6, alpha: 0.5, vx: 30, vy: -8, jitter: 10, grow: 1.4 }));
      // distant muzzle flashes / tracers on the horizon
      if (t < 2.8 || (t > 9 + this.G && t < 12.8 + this.G)) {
        this.every('dist', 5, dt, () => {
          const x = fx.r(t < 2.8 ? 700 : 100, 1880), y = fx.r(560, 780);
          fx.flash(x, y, fx.r(50, 120), 0, { layer: 'back', alpha: 0.45, life: 0.09 });
          if (fx.rnd() < 0.5) fx.tracer(x, y, fx.r(-1.2, -0.6), { layer: 'back', speed: 1400, len: 60, life: 0.35, color: '255,140,60' });
        });
      }
      // locomotive stack smoke + embers
      const lsx = this.sxOf(this.loco, t);
      if (lsx > -720 && lsx < 1960) {
        const s = this.loco.stack(lsx, this.loco.bob(lsx, t));
        this.every('stack', 26, dt, () => fx.smoke(s.x, s.y, { n: 1, vx: -90, vy: -150, size: 34, grow: 3.2, life: 2.2, alpha: 0.85, jitter: 25 }));
        this.every('stackE', 6, dt, () => fx.embers(s.x, s.y, { n: 1, spread: 10, lift: 2 }));
      }
      // wheel sparks while braking, hot rail embers under the train
      const front = off, rear = this.caboose.left + off;
      if (acc < -260) {
        this.every('brake', 40, dt, () => {
          const car = this.cars[(fx.rnd() * this.cars.length) | 0], sx = car.left + off;
          const b = car.bogies[(fx.rnd() * car.bogies.length) | 0];
          if (sx + b > 0 && sx + b < 1920) fx.sparks(sx + b + fx.r(-40, 40), 944, { n: 4, angle: -2.6, spread: 0.5, speed: 380, gravity: 900 });
        });
      }
      this.every('rail', 9, dt, () => {
        const x = fx.r(Math.max(0, rear), Math.min(1920, front));
        if (front > 0 && rear < 1920) fx.embers(x, 944, { n: 1, spread: 4 });
      });
      // scene 3 charge-up: energy converging on each gifter cannon muzzle
      for (const car of this.gifterCars) {
        const c = car.cannon;
        if (t > c.chargeFrom && t < c.chargeTo) {
          const sx = this.sxOf(car, t), m = c.muzzle(sx, car.bob(sx, t), t);
          this.every('chg' + car.g.username, 70, dt, () => {
            const a = fx.r(0, 6.283), r = fx.r(70, 150);
            fx.add({ t: 'ember', x: m.x + Math.cos(a) * r, y: m.y + Math.sin(a) * r, vx: -Math.cos(a) * r / 0.28, vy: -Math.sin(a) * r / 0.28, life: 0.28, g: 0, drag: 0, size: fx.r(2, 4), ph: 0, layer: 'front' });
          });
        }
      }
      // scene 5: embers raining from the sky
      if (t > 10.4 + this.G && t < 13 + this.G) this.every('rain', 30, dt, () => fx.embers(fx.r(200, 1720), fx.r(150, 400), { n: 1, lift: -0.6, spread: 20 }));
      // scene 6: smoke swallowing the tail
      if (t > 13.2 + this.G && t < D - 0.6) {
        const sx = this.sxOf(this.caboose, t);
        this.every('tail', 14, dt, () => fx.smoke(sx + fx.r(-20, 60), fx.r(760, 900), { n: 1, size: 90, alpha: 0.55, vx: -40, vy: -20, life: 1.6, layer: 'front' }));
      }
      this.speed = v;
    }

    // ------------------------------------------------------------- drawing --
    draw(ctx, t) {
      const off = this.off(t), v = this.vel(t), D = this.D;
      const st = { t, wheelAng: off / P.WHEEL_R, speed: Math.abs(v), tailFade: 1 - U.inv(13.9 + this.G, 14.8 + this.G, t) };
      const S = WT.cfg.trainScale || 1, Y = WT.cfg.railY;
      ctx.save();
      ctx.translate(C, Y); ctx.scale(S, S); ctx.translate(-C, -Y);
      this.drawSearchlights(ctx, t);
      this.drawGround(ctx, t, off);
      this.strikes.drawBack(ctx, t);
      this.fx.draw(ctx, 'back');
      this.drawBeam(ctx, t, off);
      const dys = [];
      for (const car of this.cars) {
        const sx = car.left + off;
        if (sx > 2150 || sx + car.w < -250) { dys.push(0); continue; }
        dys.push(car.draw(ctx, sx, st));
      }
      // couplers
      for (let i = 0; i < this.cars.length - 1; i++) {
        const a = this.cars[i], b = this.cars[i + 1];
        const x1 = b.left + b.w + off - 6, x2 = a.left + off + 6;
        if (x2 < -50 || x1 > 1970) continue;
        const y = 880 + (dys[i] + dys[i + 1]) / 2;
        ctx.fillStyle = '#0d0e10'; ctx.fillRect(x1, y - 4, x2 - x1, 8);
        P.chain(ctx, x1, y + 6, x2, y + 6, 5);
      }
      this.fx.draw(ctx, 'front');
      ctx.restore();
      this.drawHud(ctx, t);
      this.strikes.drawHud(ctx, t);
    }

    drawSearchlights(ctx, t) {
      const a = WT.cfg.warIntensity * U.envelope(t, 0.2, this.D - 1.5, 1, 1.2);
      if (a <= 0) return;
      ctx.globalCompositeOperation = 'lighter';
      [[260, 0.6, 0.0], [1680, 0.5, 2.0], [980, 0.4, 4.1]].forEach(([x, sp, ph]) => {
        const ang = -Math.PI / 2 + Math.sin(t * sp + ph) * 0.55, L = 1200;
        const ex = x + Math.cos(ang) * L, ey = 940 + Math.sin(ang) * L;
        const g = ctx.createLinearGradient(x, 940, ex, ey);
        g.addColorStop(0, `rgba(255,225,180,${0.16 * a})`); g.addColorStop(1, 'rgba(255,200,150,0)');
        ctx.fillStyle = g;
        const nx = -Math.sin(ang), ny = Math.cos(ang);
        ctx.beginPath(); ctx.moveTo(x - nx * 8, 940 - ny * 8); ctx.lineTo(ex - nx * 110, ey - ny * 110); ctx.lineTo(ex + nx * 110, ey + ny * 110); ctx.lineTo(x + nx * 8, 940 + ny * 8); ctx.fill();
      });
      ctx.globalCompositeOperation = 'source-over';
    }

    drawGround(ctx, t, off) {
      const D = this.D, rA = U.envelope(t, 0, D, 0.8, 1.0), Y = WT.cfg.railY;
      if (rA <= 0) return;
      ctx.globalAlpha = rA;
      const g = ctx.createLinearGradient(0, Y - 10, 0, Y + 60);
      g.addColorStop(0, 'rgba(10,8,7,0.0)');
      g.addColorStop(0.2, 'rgba(10,8,7,0.7)');
      g.addColorStop(1, 'rgba(10,8,7,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, Y - 10, 1920, 70);
      ctx.fillStyle = '#2a2420';
      for (let x = 0; x < 1920; x += 40) ctx.fillRect(x, Y + 4, 26, 10);
      const rg = ctx.createLinearGradient(0, Y - 4, 0, Y + 6);
      rg.addColorStop(0, '#8d949c'); rg.addColorStop(0.4, '#3a3f45'); rg.addColorStop(1, '#151719');
      ctx.fillStyle = rg;
      ctx.fillRect(0, Y - 4, 1920, 9);
      // glowing rail: faint everywhere, hot under the train
      ctx.globalCompositeOperation = 'lighter';
      const pulse = 0.22 + 0.08 * Math.sin(t * 5);
      ctx.fillStyle = `rgba(255,110,30,${pulse})`;
      ctx.fillRect(0, Y - 4, 1920, 2);
      const front = off + 600, rear = this.caboose.left + off - 300;
      const a = Math.max(0, rear), b = Math.min(1920, front);
      if (b > a) {
        const hg = ctx.createLinearGradient(rear, 0, front, 0);
        hg.addColorStop(0, 'rgba(255,90,20,0)');
        hg.addColorStop(0.15, 'rgba(255,110,30,0.55)');
        hg.addColorStop(0.85, 'rgba(255,130,40,0.55)');
        hg.addColorStop(1, 'rgba(255,90,20,0)');
        ctx.fillStyle = hg;
        ctx.fillRect(a, Y - 6, b - a, 5);
        ctx.globalAlpha = rA * 0.5;
        ctx.fillRect(a, Y - 18, b - a, 16);
      }
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
    }

    drawBeam(ctx, t, off) {
      const lsx = this.sxOf(this.loco, t);
      const h = this.loco.headlight(lsx, this.loco.bob(lsx, t));
      if (h.x > 2100) return;
      const a = U.envelope(t, 0.1, 6, 0.8, 1.5) * (0.9 + 0.1 * Math.sin(t * 40));
      if (a <= 0) return;
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = a;
      const g = ctx.createLinearGradient(h.x, 0, h.x + 1100, 0);
      g.addColorStop(0, 'rgba(255,200,140,0.45)');
      g.addColorStop(0.3, 'rgba(255,140,60,0.16)');
      g.addColorStop(1, 'rgba(255,120,40,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(h.x, h.y - 10); ctx.lineTo(h.x + 1100, h.y - 170); ctx.lineTo(h.x + 1100, h.y + 190); ctx.lineTo(h.x, h.y + 10);
      ctx.closePath();
      ctx.fill();
      // glare when the lamp is still hidden behind the left edge: "lights emerging from the smoke"
      P.glowSprite(ctx, WT.sprites.orange, Math.max(h.x, -40), h.y, 420, a * 0.7);
      P.glowSprite(ctx, WT.sprites.white, Math.max(h.x, -40), h.y, 160, a * 0.8);
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
    }

    drawHud(ctx, t) {
      const G = this.G, L = WT.cfg.labels;
      // Scene 1: tactical "incoming" readout
      const ia = U.envelope(t, 0.25, 2.7, 0.2, 0.4);
      if (ia > 0) {
        ctx.globalAlpha = ia * (Math.sin(t * 18) > -0.6 ? 1 : 0.4);
        const txt = L.incoming.slice(0, Math.floor(U.inv(0.3, 1.2, t) * L.incoming.length));
        ctx.fillStyle = ACCENT;
        ctx.beginPath(); ctx.moveTo(130, 452); ctx.lineTo(150, 488); ctx.lineTo(110, 488); ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#111'; ctx.font = `bold 24px ${P.FONT_UI}`; ctx.textAlign = 'center'; ctx.fillText('!', 130, 484);
        P.glowText(ctx, txt, 170, 472, 34, '#ffd2a8', { align: 'left', glowColor: ACCENT, blur: 14 });
        ctx.fillStyle = 'rgba(255,122,26,0.6)';
        ctx.fillRect(110, 500, 520 * U.inv(0.3, 1.4, t), 2);
        ctx.globalAlpha = 1;
      }
      // Scene 4: hype train level-up / completion banner above the HYPE TRAIN wagon
      const hy = this.p.hype;
      if (hy && hy.event) {
        const ba = U.envelope(t, 6.6 + G, 9.8 + G, 0.3, 0.5);
        if (ba > 0) {
          const hx = U.clamp(this.sxOf(this.hype, t) + this.hype.w / 2, 360, 1560);
          const s = U.easeOutBack(U.inv(6.6 + G, 7.0 + G, t));
          ctx.save(); ctx.globalAlpha = ba; ctx.translate(hx, 600); ctx.scale(s, s);
          const txt = hy.event === 'complete' ? `HYPE TRAIN COMPLETE — LEVEL ${hy.level}` : `HYPE TRAIN LEVEL ${hy.level}!`;
          P.glowText(ctx, txt, 0, 0, 50, GOLD, { glowColor: ACCENT, core: '#fff1cc', blur: 26 });
          ctx.restore();
        }
      }
      // Scene 5: THANK YOU, SUB GIFTERS!
      const ta = U.envelope(t, 10.15 + G, 13.9 + G, 0.15, 0.9);
      if (ta > 0) this.drawThanks(ctx, t, ta);
    }

    drawThanks(ctx, t, alpha) {
      const G = this.G, L = WT.cfg.labels, t0 = 10.15 + G;
      ctx.save();
      ctx.globalAlpha = alpha;
      // soft dark backing so the text stays readable over any game
      const bg = ctx.createLinearGradient(0, 220, 0, 520);
      bg.addColorStop(0, 'rgba(0,0,0,0)'); bg.addColorStop(0.3, 'rgba(5,4,3,0.55)'); bg.addColorStop(0.75, 'rgba(5,4,3,0.55)'); bg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 220, 1920, 300);
      // title slam
      const k = U.inv(t0, t0 + 0.35, t), s = 1.7 - 0.7 * U.easeOutCubic(k);
      ctx.save();
      ctx.translate(C, 300);
      ctx.scale(s, s);
      ctx.font = `86px ${P.FONT_STENCIL}`;
      const size = U.fitFont(ctx, L.thanks, 1500, 86, P.FONT_STENCIL);
      P.glowText(ctx, L.thanks, 0, 0, size, ACCENT, { core: '#ffe6cc', blur: 30 });
      ctx.restore();
      if (k < 1) P.glowSprite(ctx, WT.sprites.white, C, 300, 1200 * (1 - k), (1 - k) * 0.6);
      // rule lines
      const lw = 700 * U.easeOutCubic(U.inv(t0 + 0.2, t0 + 0.7, t));
      ctx.fillStyle = ACCENT;
      ctx.fillRect(C - lw, 352, lw * 2, 2);
      // roster chips (most recent gifters) — measured so they never overlap
      const list = this.p.recent.slice(0, 5);
      ctx.font = `700 30px ${P.FONT_UI}`;
      let fs = 30;
      const measure = () => list.map((g) => ctx.measureText(`${U.cleanName(g.username)}  ×${g.giftCount}`).width + 76);
      let widths = measure();
      while (widths.reduce((a, b) => a + b, 0) + (list.length - 1) * 18 > 1760 && fs > 16) {
        fs -= 2; ctx.font = `700 ${fs}px ${P.FONT_UI}`; widths = measure();
      }
      const total = widths.reduce((a, b) => a + b, 0) + (list.length - 1) * 18;
      let cx = C - total / 2;
      list.forEach((g, i) => {
        const a = U.inv(t0 + 0.45 + i * 0.12, t0 + 0.75 + i * 0.12, t);
        if (a > 0) {
          const w = widths[i], y = 390 + (1 - U.easeOutBack(a)) * 30;
          ctx.globalAlpha = alpha * a;
          ctx.fillStyle = 'rgba(10,10,11,0.9)';
          U.chamfer(ctx, cx, y, w, fs + 26, 8); ctx.fill();
          ctx.strokeStyle = i === 0 ? GOLD : ACCENT; ctx.lineWidth = 2; ctx.stroke();
          P.crown(ctx, cx + 30, y + (fs + 26) / 2, fs * 0.9, GOLD);
          ctx.font = `700 ${fs}px ${P.FONT_UI}`; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
          ctx.fillStyle = '#f4efe6';
          const nm = U.cleanName(g.username);
          ctx.fillText(nm, cx + 56, y + (fs + 26) / 2 + 1);
          ctx.fillStyle = GOLD;
          ctx.fillText(`×${g.giftCount}`, cx + 56 + ctx.measureText(nm + '  ').width, y + (fs + 26) / 2 + 1);
        }
        cx += widths[i] + 18;
      });
      // animated total counter
      ctx.globalAlpha = alpha * U.inv(t0 + 0.6, t0 + 0.9, t);
      const cr = this.p.counter;
      const cnt = Math.round(U.lerp(cr[0], cr[1], U.easeOutCubic(U.inv(t0 + 0.6, t0 + 1.8, t))));
      P.glowText(ctx, `${L.total}: ${cnt}`, C, 474, 34, GOLD, { font: P.FONT_STENCIL, glowColor: ACCENT, blur: 16 });
      ctx.restore();
    }
  }

  WT.Run = Run;
})(window.WT);

/* ---- js/events/controller.js ---- */
/* War Train — event queue + run scheduler.
   Events never interrupt a running train: they are queued and picked up by the next pass. */
window.WT = window.WT || {};
(function (WT) {
  'use strict';
  const U = WT.U;
  const TYPES = ['sub', 'resub', 'gift', 'hypetrain_levelup', 'hypetrain_progress', 'hypetrain_end'];

  // Normalised event shape used everywhere in the overlay:
  // { id, type, username, avatarUrl, count, tier, months, level, progress, goal }
  WT.normalize = function (raw) {
    if (!raw || TYPES.indexOf(raw.type) < 0) return null;
    const e = {
      id: String(raw.id || raw.eventId || `${raw.type}-${raw.username || ''}-${raw.count || ''}-${Date.now()}-${Math.random()}`),
      type: raw.type,
      username: U.cleanName(raw.username || raw.name || raw.user_name),
      avatarUrl: typeof raw.avatarUrl === 'string' && /^https?:\/\//.test(raw.avatarUrl) ? raw.avatarUrl : '',
      count: Math.max(1, Math.min(1000, parseInt(raw.count || raw.amount || 1, 10) || 1)),
      tier: String(raw.tier || '1000'),
      months: Math.max(1, parseInt(raw.months || 1, 10) || 1),
      level: Math.max(1, parseInt(raw.level || 1, 10) || 1),
      progress: +raw.progress || 0,
      goal: +raw.goal || 0,
    };
    return e;
  };

  class TrainController {
    constructor(cfg, fx, sound) {
      this.cfg = cfg;
      this.fx = fx;
      this.sound = sound;
      this.clock = 0;
      this.run = null;
      this.runT = 0;
      this.pendingGifters = [];
      this.pendingRecruits = [];
      this.pendingHype = null;
      this.hype = { level: 1, progress: 0, goal: 0 };
      this.wakeAt = Infinity;
      this.seen = [];
      this.demoIdx = 0;
      this.listeners = [];
      this.recent = [];
      this.totalGifts = 0;
      this.load();
    }

    on(fn) { this.listeners.push(fn); }
    emit(kind, data) { for (const fn of this.listeners) try { fn(kind, data); } catch (e) { /* ignore */ } }

    load() {
      if (!this.cfg.persist) return;
      try {
        const s = JSON.parse(localStorage.getItem('wartrain.state') || 'null');
        if (s) { this.recent = s.recent || []; this.totalGifts = s.totalGifts || 0; }
      } catch (e) { /* storage unavailable — start fresh */ }
    }
    save() {
      if (!this.cfg.persist) return;
      try { localStorage.setItem('wartrain.state', JSON.stringify({ recent: this.recent.slice(0, 10), totalGifts: this.totalGifts })); } catch (e) { /* ignore */ }
    }
    resetStats() { this.recent = []; this.totalGifts = 0; this.save(); this.emit('stats'); }

    // Entry point for every integration (mock, StreamElements, SSE relay, custom code).
    handle(raw) {
      const e = WT.normalize(raw);
      if (!e) return false;
      if (this.seen.indexOf(e.id) >= 0) return false; // duplicate delivery
      this.seen.push(e.id);
      if (this.seen.length > 300) this.seen.shift();
      const trig = this.cfg.triggerOn;

      if (e.type === 'gift') {
        // merge rapid repeat gifts from the same person into one wagon (only while still queued)
        const same = this.pendingGifters.find((g) => g.username.toLowerCase() === e.username.toLowerCase() && this.clock - g.at < this.cfg.aggregateWindowMs / 1000);
        if (same) { same.giftCount += e.count; same.at = this.clock; }
        else {
          const g = { username: e.username, avatarUrl: e.avatarUrl, giftCount: e.count, tier: e.tier, eventId: e.id, at: this.clock };
          this.pendingGifters.push(g);
          if (!g.avatarUrl && this.cfg.avatarLookup === 'decapi' && e.username !== 'Anonymous') this.lookupAvatar(g);
        }
        if (trig.gift) this.arm();
      } else if (e.type === 'sub' || e.type === 'resub') {
        this.pendingRecruits.push({ username: e.username, type: e.type, months: e.months });
        if (this.pendingRecruits.length > 8) this.pendingRecruits.shift();
        if (trig[e.type]) this.arm();
      } else if (e.type === 'hypetrain_progress') {
        Object.assign(this.hype, { level: e.level, progress: e.progress, goal: e.goal });
      } else if (e.type === 'hypetrain_levelup') {
        Object.assign(this.hype, { level: e.level, progress: e.progress || this.hype.progress, goal: e.goal || this.hype.goal, complete: false });
        this.pendingHype = { event: 'levelup', level: e.level };
        if (trig.hypetrain) this.arm();
      } else if (e.type === 'hypetrain_end') {
        Object.assign(this.hype, { level: e.level, complete: true, progress: 1, goal: 1 });
        this.pendingHype = { event: 'complete', level: e.level };
        if (trig.hypetrain) this.arm();
      }
      this.emit('event', e);
      this.emit('queue');
      return true;
    }

    lookupAvatar(g) {
      fetch(`https://decapi.me/twitch/avatar/${encodeURIComponent(g.username)}`)
        .then((r) => r.text())
        .then((u) => { u = u.trim(); if (/^https:\/\//.test(u)) g.avatarUrl = u; })
        .catch(() => {});
    }

    arm() {
      const at = this.clock + this.cfg.startDelayMs / 1000;
      if (this.wakeAt === Infinity) this.wakeAt = at;
    }

    hasWork() {
      return this.pendingGifters.length > 0 || this.pendingHype || this.pendingRecruits.length > 0;
    }

    startRun(demo) {
      const cfg = this.cfg;
      let gifters, recruits, hype, recent, counter;
      if (demo) {
        // preview / prerender pass: rotate through the demo gifters, never touch real stats
        const d = cfg.demo.gifters, i = this.demoIdx++ % d.length;
        gifters = [Object.assign({}, d[i])];
        recruits = cfg.demo.recruits.slice();
        hype = Object.assign({}, cfg.demo.hype);
        recent = d.slice(i).concat(d.slice(0, i));
        const base = 120 + i * 7;
        counter = [base, base + gifters[0].giftCount];
      } else {
        gifters = this.pendingGifters.splice(0, cfg.maxGiftersPerRun);
        recruits = this.pendingRecruits.splice(0, 4);
        hype = Object.assign({}, this.hype, this.pendingHype || {});
        this.pendingHype = null;
      }
      if (!demo) {
        recent = gifters.slice().reverse().concat(this.recent.filter((r) => !gifters.some((g) => g.username === r.username))).slice(0, 5);
        const thisRun = gifters.reduce((a, g) => a + g.giftCount, 0);
        counter = [this.totalGifts, this.totalGifts + thisRun];
      }
      this.run = new WT.Run(this, { gifters, recruits, hype, recent, counter, demo: !!demo });
      this.runT = 0;
      this.wakeAt = Infinity;
      this.emit('run', this.run);
      this.emit('queue');
    }

    // Called by a Run when a gifter's cannon fires: counts the gifts and updates the roster.
    onGifterFired(g) {
      if (this.run && this.run.p.demo) return; // demo passes never change real stats
      this.totalGifts += g.giftCount;
      this.recent = [{ username: g.username, giftCount: g.giftCount }].concat(this.recent.filter((r) => r.username !== g.username)).slice(0, 10);
      this.save();
      this.emit('stats');
    }

    tick(dt) {
      this.clock += dt;
      if (this.run) {
        this.runT += dt;
        this.run.update(this.runT, dt);
        if (this.runT >= this.run.D) {
          this.run = null;
          this.emit('idle');
          if (this.hasWork()) this.wakeAt = this.clock + 0.3;
        }
      }
      if (!this.run) {
        if (this.hasWork() && this.clock >= this.wakeAt) { this.wakeAt = Infinity; this.startRun(false); }
        else if (!this.hasWork() && this.cfg.mode === 'loop') this.startRun(true);
      }
      this.fx.update(dt);
    }

    draw(ctx) {
      if (this.run) this.run.draw(ctx, this.runT);
      else { this.fx.draw(ctx, 'back'); this.fx.draw(ctx, 'front'); }
    }
  }

  WT.TrainController = TrainController;
})(window.WT);

/* ---- js/events/adapters.js ---- */
/* War Train — event sources. Each adapter turns provider-specific payloads into normalised events
   and hands them to controller.handle(). No secrets or tokens ever live in this file. */
window.WT = window.WT || {};
(function (WT) {
  'use strict';

  // ---- StreamElements custom widget --------------------------------------------------------
  // Inside a StreamElements custom widget, SE dispatches `onEventReceived` on window.
  // Sub events (listener "subscriber-latest") carry: name, amount, tier, gifted, sender,
  // bulkGifted (community gift by `sender`), isCommunityGift (one recipient of a bulk gift).
  WT.fromStreamElements = function (detail) {
    if (!detail || !detail.event) return null;
    const L = detail.listener, e = detail.event;
    const id = e._id || e.activityId || undefined;
    if (L === 'subscriber-latest') {
      if (e.isCommunityGift) return null; // recipients of a community gift — the bulk event counts it
      if (e.bulkGifted) return { type: 'gift', id, username: e.sender || e.name, count: e.amount, tier: e.tier };
      if (e.gifted) return { type: 'gift', id, username: e.sender || 'Anonymous', count: 1, tier: e.tier };
      if ((+e.amount || 1) > 1) return { type: 'resub', id, username: e.name, months: e.amount, tier: e.tier };
      return { type: 'sub', id, username: e.name, tier: e.tier };
    }
    // Hype train listeners differ per SE account/version; this mapping is best-effort.
    if (/hypetrain/i.test(L || '')) {
      if (/end|complete/i.test(L)) return { type: 'hypetrain_end', id, level: e.level || e.amount };
      if (/level/i.test(L)) return { type: 'hypetrain_levelup', id, level: e.level || e.amount, progress: e.progress, goal: e.goal };
      return { type: 'hypetrain_progress', id, level: e.level, progress: e.progress, goal: e.goal };
    }
    return null;
  };

  WT.connectStreamElements = function (ctrl) {
    window.addEventListener('onEventReceived', (obj) => {
      const ev = WT.fromStreamElements(obj && obj.detail);
      if (ev) ctrl.handle(ev);
    });
  };

  // ---- Local relay (server/server.mjs) via Server-Sent Events ------------------------------
  // The relay holds the Twitch credentials server-side and pushes already-normalised JSON.
  WT.connectSSE = function (ctrl, url) {
    if (!url || !window.EventSource) return null;
    let es, retry = 1000;
    const open = () => {
      es = new EventSource(url);
      es.onopen = () => { retry = 1000; ctrl.emit('source', { sse: 'connected' }); };
      es.onmessage = (m) => { try { ctrl.handle(JSON.parse(m.data)); } catch (e) { /* ignore bad frame */ } };
      es.onerror = () => {
        ctrl.emit('source', { sse: 'reconnecting' });
        es.close();
        setTimeout(open, retry);
        retry = Math.min(retry * 2, 15000);
      };
    };
    open();
    return { close: () => es && es.close() };
  };

  // ---- Mock events for local testing -------------------------------------------------------
  const NAMES = ['Reaper_Six', 'DeadEye_Dutch', 'OverlordNL', 'Kilo141', 'SnipeQueen', 'TacticalTaco', 'Bravo_Two', 'Havoc_X',
    'IronSights', 'NoScopeNora', 'Gh0stLyfe', 'ChopperDown', 'Warlord_Wim', 'Stealth_Sanne', 'CaptainCrunchtime'];
  let n = 0;
  const pick = () => NAMES[Math.floor(Math.random() * NAMES.length)];
  WT.mock = {
    names: NAMES,
    sub: (name) => ({ type: 'sub', id: 'mock-' + ++n, username: name || pick(), tier: '1000' }),
    resub: (name, months) => ({ type: 'resub', id: 'mock-' + ++n, username: name || pick(), months: months || 2 + Math.floor(Math.random() * 30) }),
    gift: (count, name, tier) => ({ type: 'gift', id: 'mock-' + ++n, username: name || pick(), count: count || 1, tier: tier || '1000' }),
    hypeLevel: (level) => ({ type: 'hypetrain_levelup', id: 'mock-' + ++n, level: level || 2, progress: 300 + Math.floor(Math.random() * 600), goal: 1000 }),
    hypeEnd: (level) => ({ type: 'hypetrain_end', id: 'mock-' + ++n, level: level || 5 }),
    random: () => {
      const r = Math.random();
      if (r < 0.45) return WT.mock.gift([1, 1, 5, 10, 20][Math.floor(Math.random() * 5)]);
      if (r < 0.7) return WT.mock.sub();
      if (r < 0.9) return WT.mock.resub();
      return WT.mock.hypeLevel(2 + Math.floor(Math.random() * 4));
    },
    start: (ctrl, seconds) => setInterval(() => ctrl.handle(WT.mock.random()), (seconds || 9) * 1000),
  };
})(window.WT);

/* ---- js/main.js ---- */
/* War Train — bootstrap: canvas sizing, render loop, event sources and the public window.WarTrain API. */
window.WT = window.WT || {};
(function (WT) {
  'use strict';

  function waitFonts(ms) {
    if (!document.fonts || !document.fonts.load) return Promise.resolve();
    const loads = ['40px "Black Ops One"', '700 40px Oswald', '500 20px Oswald'].map((f) => document.fonts.load(f).catch(() => {}));
    return Promise.race([Promise.all(loads), new Promise((r) => setTimeout(r, ms))]);
  }

  WT.boot = async function (opts) {
    opts = opts || {};
    const cfg = (WT.cfg = WT.makeConfig(opts.config));
    const canvas = opts.canvas || document.getElementById('wt-canvas');
    const ctx = canvas.getContext('2d', { alpha: true });
    const params = new URLSearchParams(location.search);
    const exportMode = params.get('export') === '1';

    await waitFonts(3000);

    const fx = new WT.FX(cfg.quality);
    WT.sprites = fx.sprites;
    const sound = new WT.Sound(cfg.sound);
    const ctrl = new WT.TrainController(cfg, fx, sound);

    // Resolution: always render the 1920×1080 design space, scaled to the actual canvas size.
    let scale = 1;
    function resize() {
      if (exportMode) { canvas.width = cfg.width; canvas.height = cfg.height; scale = 1; return; }
      const rect = canvas.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = Math.max(320, Math.round(rect.width * dpr)), h = Math.round((w * cfg.height) / cfg.width);
      if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
      scale = w / cfg.width;
    }
    resize();
    window.addEventListener('resize', resize);

    function render() {
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height); // true alpha: nothing painted = transparent
      const sh = fx.shakeOffset(ctrl.clock);
      ctx.setTransform(scale, 0, 0, scale, sh[0] * scale, sh[1] * scale);
      ctrl.draw(ctx);
    }

    // Sources
    if (cfg.source === 'auto' || cfg.source === 'streamelements') WT.connectStreamElements(ctrl);
    if (cfg.sseUrl && cfg.source !== 'none') WT.connectSSE(ctrl, cfg.sseUrl);
    if (cfg.source === 'mock') WT.mock.start(ctrl, cfg.mockInterval);

    // Loop (fixed-step simulation keeps particles stable at any refresh rate)
    const STEP = 1 / 60;
    let last = performance.now(), accT = 0, frames = 0, fpsT = 0;
    const api = (window.WarTrain = {
      config: cfg, controller: ctrl, sound, fx, fps: 0,
      handle: (ev) => ctrl.handle(ev),
      mock: WT.mock,
      setSound: (on) => sound.setEnabled(on),
      replayDemo: () => { if (!ctrl.run) ctrl.startRun(true); },
      // Export helpers (used by tools/render-webm.mjs): step exactly one 60fps frame and return a PNG.
      exportFrame: () => { ctrl.tick(STEP); render(); return canvas.toDataURL('image/png'); },
      step: (n) => { for (let i = 0; i < n; i++) ctrl.tick(STEP); render(); },
      runDuration: () => (ctrl.run ? ctrl.run.D : 0),
    });

    if (!exportMode) {
      const frame = (now) => {
        let dt = (now - last) / 1000;
        last = now;
        if (dt > 0.25) dt = 0.25; // tab was hidden: don't fast-forward through a whole scene
        accT += dt;
        while (accT >= STEP) { ctrl.tick(STEP); accT -= STEP; }
        render();
        frames++; fpsT += dt;
        if (fpsT >= 0.5) { api.fps = Math.round(frames / fpsT); frames = 0; fpsT = 0; }
        requestAnimationFrame(frame);
      };
      requestAnimationFrame(frame);
    }
    if (opts.onReady) opts.onReady(api);
    return api;
  };
})(window.WT);

/* ---- StreamElements boot ---- */
window.addEventListener('onWidgetLoad', function (obj) {
  var f = (obj && obj.detail && obj.detail.fieldData) || {};
  window.WAR_TRAIN_CONFIG = {
    source: 'streamelements',
    mode: f.loopDemo === true || f.loopDemo === 'true' ? 'loop' : 'events',
    quality: f.quality || 'high',
    maxGiftersPerRun: +f.maxGifters || 3,
    persist: true,
    sound: { enabled: f.soundEnabled === true || f.soundEnabled === 'true', volume: f.volume != null ? +f.volume : 0.5 },
    labels: {
      gifter: f.labelGifter || 'SUB GIFTER', hype: f.labelHype || 'HYPE TRAIN', blackops: f.labelBlackops || 'BLACK OPS',
      warzone: f.labelWarzone || 'WARZONE', thanks: f.labelThanks || 'THANK YOU, SUB GIFTERS!'
    }
  };
  WT.boot();
});
